window.HARDTRP.receive("114768",[[114769,"2026-07-14T17:16:14",9,"Начало темы.\n\n@sweetkittywitch — Дм этой темы.",114768,null],[114770,"2026-07-14T17:22:11",41,"Красота",114768,null],[114771,"2026-07-14T17:22:22",41,"Ща музыку послушаю и начнем",114768,null],[114772,"2026-07-14T17:22:36",42,"Красота это когда на душе сладко и хочется улыбаться",114768,null],[114773,"2026-07-14T17:25:27",0,"Хм",114768,null],[114774,"2026-07-14T17:25:38",42,"Тогда я всех тегаю\n@tochhkatochka \n@Xaosick",114768,null],[114775,"2026-07-14T17:27:05",42,"Игра, щас будет приключение с первого уровня у всех. Надеюсь персонажи наши споются, ибо все мои приколы работают если существа в мире и дружат между собою ;)",114768,null],[114778,"2026-07-14T17:29:22",41,"( такс, готова. Представьте своих персонажей в небольших постах характиризующих их нынешний этап развития. Пост играет роль представления персонажа, а не прохода в ролевую локацию. Последним займусь я",114768,null],[114782,"2026-07-14T17:31:59",42,"Люми тифлинг что считает себя богом \"счастливой и безаботной жизни\". Его сила не берëтся от божеств, а от его паствы, магия Люми не может ранить ибо она создана от добрых умыслов и улыбки.",114768,null],[114785,"2026-07-14T17:35:24",0,"Стэт лысый",114768,null],[114786,"2026-07-14T17:37:19",9,"//Это лучшое представление персонажа перед квестом за всё время что я видел 😏👌",114785,null],[114789,"2026-07-14T17:37:58",32,"Я занят подойдите 15-20 минут",114768,null],[114790,"2026-07-14T17:38:12",41,"( оке",114768,null],[114791,"2026-07-14T17:38:41",42,"// Оки, ждëм лидера",114789,null],[114792,"2026-07-14T17:39:49",41,"( лидера? Ммм",114791,null],[114793,"2026-07-14T17:40:22",42,"// у него рыцарь пурпурного дракона, это подкласс воеводы воина",114792,null],[114794,"2026-07-14T17:40:53",42,"// ну это правда. Надо ему себя показать чтобы назваться лидером, пока только Люми бог тут",114768,null],[114795,"2026-07-14T17:41:07",11,"// я надеюсь Жак будет его лысину наглаживать",114785,null],[114796,"2026-07-14T17:41:57",42,"// Конечно, всех он любит",114795,null],[114797,"2026-07-14T17:42:12",11,"// кидайте потом в эпик что бы я заценила😁",114796,null],[114800,"2026-07-14T17:47:50",41,"Текс, жду дракончика",114768,null],[114801,"2026-07-14T17:47:58",41,"Оформление почти готово",114768,null],[114834,"2026-07-14T18:09:15",42,"// @Xaosick  яяяя-я-яяя-ааа вызываю тебя, во имя мяса и хлеба с похлëбкой из курочки",114768,null],[114847,"2026-07-14T18:20:15",41,"Туц туц туц",114768,null],[114849,"2026-07-14T18:21:45",32,"Так я наконец вернулся!",114768,null],[114850,"2026-07-14T18:21:59",32,"Простите что очень долго",114768,null],[114853,"2026-07-14T18:22:20",41,"ОМАГАД",114768,null],[114856,"2026-07-14T18:22:56",42,"Арминар у дк",114768,null],[114861,"2026-07-14T18:23:28",32,"Ещё раз простите тогда у меня нет картинки",114856,null],[114863,"2026-07-14T18:23:45",32,"Просто благородный рыцарь",114768,null],[114867,"2026-07-14T18:24:35",41,"Умница",114857,null],[114870,"2026-07-14T18:25:25",42,"Плазмоид, так что будет легче. Слизь есть слизь",114863,null],[114874,"2026-07-14T18:26:00",41,"Красавец какой!",114873,null],[114875,"2026-07-14T18:26:27",41,"Всё, не флудите пж, щас будет стартовый пост",114768,null],[114881,"2026-07-14T18:30:03",41,"Включаю пластинку:",114768,null],[114886,"2026-07-14T18:32:31",32,"/а может и я кину что-нибудь подходящее?",114768,null],[114887,"2026-07-14T18:32:46",41,"( всем можно",114768,null],[114889,"2026-07-14T18:33:37",42,"// я руки целовал музыкальному вкусу",114882,null],[114890,"2026-07-14T18:33:44",32,"https://youtu.be/dDIYd_5rmYc?si=ZM4ncn-yhc-wOBRL",114768,null],[114891,"2026-07-14T18:33:57",32,"Тема под сера жыжу",114768,null],[114898,"2026-07-14T18:39:42",0,"Хм",114768,null],[114917,"2026-07-14T18:47:39",41,"Лисьи лапы идут позади вас, прикрывая ваш тыл. Соломинки, выпавшие из недавно проехавшей мимо повозки, застревают у него в лапах, заставляя отряхиваться.\n\nОдетый в походный костюм зверек огрызается:\n\n— Вот же кляча старая, уже лошадей нормальных найти не могут! Тьфу!\n\nПереводя носатую морду на вас, он начинает свой рассказ:\n\n— Значит так, безработные: какая бы особенная кровь ни текла в ваших венах, я крайне не уверен, что вы справитесь лучше, чем две дюжины людей с высшим образованием. И ведь кто ведет вас на верную гибель? Правильно — Старина Элрен! А потом ведь мне к психологу ходить... Подумали бы о моем здоровье!\n\nЛис продолжал ворчать.",114768,null],[114922,"2026-07-14T18:50:05",0,"—лис не ворчи\n—запомни работа не волк\n—никто не волк \n—только волк волк",114917,null],[114927,"2026-07-14T18:51:47",42,"— Апхахах.. Забавно звучит.. Ииии.. Поэтично, мне это очень и оооооочеееень нравится! \n°приобнял поэта словно своë детя и улыбается от бесконечного притока счастья°",114922,null],[114931,"2026-07-14T18:53:37",0,"—я великий мудрец знаю много",114927,null],[114934,"2026-07-14T18:53:52",0,"—если закрыть глаза будет темно",114768,null],[114935,"2026-07-14T18:54:00",41,"--- Да как смеешь ты называть меня лисом?! Это очень по расистки и оскорбительно с твоей стороны, знаешь?! \n\nЯ вообще-то гномом был, похожим на тебя, но с шикарными волосами! \n\nЗверь гордо распушился",114922,null],[114940,"2026-07-14T18:55:57",0,"—ну настоящий мужчина как ковер с каждым годом лысеет",114935,null],[114942,"2026-07-14T18:56:26",42,"— Не какой злобы и противопоставлений, с вами бог мира и счастья, не подобает чтобы в моë присутствие ругались, а то будете мириться за мизинцы\n°надул щëки и смотрит на этих глупышек°",114768,null],[114945,"2026-07-14T18:57:45",0,"—запомни \n—Мама учила не ругаться матом, но жизнь научила не ругаться матом при маме",114942,null],[114949,"2026-07-14T18:59:54",41,"Элрен противно хихикая, закатил глаза и продолжил вас вести. \n\n--- Что ж с вами делать? Вы так и с разбойниками -  желающими продать ваши органы, общаться будете?",114768,null],[114950,"2026-07-14T19:00:02",42,"— Забавный ты слишком для моего великолепия, пойду попристаю к рыцарю\n°потопал к рыцарю чтобы позадавать много глыпых но развлекающих его вопросы°",114768,null],[114951,"2026-07-14T19:00:23",32,"Сер Ривелон шел редом. Пурпурная слизь смотрел на руку и сказал. \n-А я слизь может был таким всегда но форму поменял сегодня.\n(Решил поддержать парад простых мудростей которые очевидности)",114945,null],[114955,"2026-07-14T19:01:17",0,"—Надо сохранить свою мудрость а то уже не молодой",114949,null],[114963,"2026-07-14T19:02:26",42,"— Как положено говорить.. Эээмм.. Сер.. Сыр.. Сир...?",114768,null],[114970,"2026-07-14T19:04:39",42,"— Ладно, будешь называться у меня Сер слизи",114768,null],[114988,"2026-07-14T19:08:26",41,"Лис машет вам, указывая за холм. \n\n--- Вон там деревня, за этим цветущим холмом! По заданию всё помните? Вопросов нет? \n\n--- Нет??? \n\n--- На сим я вас покидаю \n\nРазворачивая ногу вокруг своей оси на 180, зверек уходит.",114768,null],[114993,"2026-07-14T19:09:47",0,"—удачи\n—Запомни простое правило: левая сторона — это правая, если развернуться на 180 градусов. Но если развернуться дважды — ты просто дурак, который крутится на месте",114988,null],[114994,"2026-07-14T19:09:49",32,"Мне кажется он даже не выслушал что мы хотели сказать? Или я ошибаюсь",114988,null],[115000,"2026-07-14T19:11:39",41,"( не выслушал",114994,null],[115004,"2026-07-14T19:12:56",0,"Осматриваюсь",114768,null],[115007,"2026-07-14T19:14:22",41,"Как вам и сказал Элрен. Уже за холмом вас ждет деревня. И правда, на верхушке холма видно козу, пока всего одну",114768,null],[115010,"2026-07-14T19:14:39",0,"Иду к козе*",114768,null],[115026,"2026-07-14T19:20:53",0,"//хм",114768,null],[115030,"2026-07-14T19:23:17",41,"Коза слегка отошла от подходящего к ней человека. \n\nСам бард слышал пение из за забора, откуда шел молодой постух - гоблин. \n\n--- Морена моя, морена моя, морена - люблю я тебя ~ \n\nТак и чуть не стукнулся о тебя\n\n--- Ой! Здравствуйте, господин. Вы кого-то ищите? Ромашка точно заметила вас раньше, чем вы её, она тут следит за всеми лучше меня.",114768,null],[115033,"2026-07-14T19:26:09",41,"( вы идете за ним же?",114768,null],[115039,"2026-07-14T19:27:54",0,"—привет гоблин \n—как зовут",114768,null],[115045,"2026-07-14T19:30:08",41,"Гоблин/Могго\n\n--- Я Могго, самый умный пастух в деревне. Потому что я никогда никого не сужу. А вы кем будете? \n\nОпираясь на свою палку, ответил парень",114768,null],[115050,"2026-07-14T19:31:42",0,"—я стэт и я знаю одну мудрость\n—Думать вредно. От мыслей появляются сомнения. От сомнений — страх. А от страха — мокрые штаны. Видишь мои штаны? Они сухие. Именно поэтому я не думаю",115045,null],[115060,"2026-07-14T19:35:41",41,"Могго \n\n--- Что ж, возможно мне стоит прислушаться к твоим словам. Но не будем про штаны. Скажи мне, ты потепялся?",115050,null],[115063,"2026-07-14T19:36:07",42,"— Могго, видно увидев тебя я сразу же понял что ты парень очень умëн. Можешь нам что-то интересное рассказать? \n°подошëл к гоблину и обнял его°",115045,null],[115067,"2026-07-14T19:36:49",42,"/roll +d20 +5 убеждение на его раскрытость",114768,null],[115070,"2026-07-14T19:37:44",41,"( Не поняла. Он пытается обокрасть или убедить?",114768,null],[115073,"2026-07-14T19:38:36",42,"// убеждение, чтобы могго был спокоен от его объятий и рассказал Люми что-то занимающее",114768,null],[115074,"2026-07-14T19:38:41",0,"—я не теряюсь \n—я не знаю где я \n—а иду в деревню за холмом",115060,null],[115079,"2026-07-14T19:40:38",41,"--- Ой мужик. Ты конечно мягкий и теплый, но я такого не ожидал. В следующий раз и палкой вдарить могу. \n\nТот растерялся, но обнял Люми\n\n--- Всё, всё. Отпусти. Вы вместе что-ли? Решили переехать в нашу прекрасную деревню?",115073,null],[115081,"2026-07-14T19:43:05",0,"—люди пропали в лесу сейчас в деревню потом в лес искать причину",115079,null],[115082,"2026-07-14T19:44:30",41,"Могго\n\n--- Ага-а-а. Вы эти...ава...пендю...ава..А! Авантюристы! Во! \n\nКхм-кхм. \n\nОн слегка постукал Люми палочкой",114768,null],[115083,"2026-07-14T19:44:35",42,"— пхех.. Ну хорошо. Главное чтоб тебе было спокойнее\n°отпустил от объятий и просто встал рядом с синонимом поэзии нулевых°",115079,null],[115084,"2026-07-14T19:45:21",0,"—могго \n—ты думал \n—а это первая ошибка авантюриста",115082,null],[115087,"2026-07-14T19:49:44",41,"Могго\n\n--- А я не авантюрист. Вы вроде про пропавших людей хотели узнать. Ну было дело... Пришла некая знатная дама с тех островов на востоке. А с ней и какие-то горделивые мужчины с бумагами, лупами и кристаллами. \n\nМогго показательно изобразил \"очки \" умных азиатов, играя кистями рук\n\n--- Ну старейшина Гифлий послушал их, подписал там что-то и боится теперь. Да так, Что дома заперся. \n\nЗря фигней страдает, Наму то из леса не выходит.",115084,null],[115088,"2026-07-14T19:51:48",0,"—что за гифлей",115087,null],[115089,"2026-07-14T19:52:28",41,"Могго \n\n--- Старейшина наш. Я ж сказал. Дед такой, седой и высокий",115088,null],[115090,"2026-07-14T19:52:52",0,"—могго а ты когда-нибудь пил пиво",115089,null],[115091,"2026-07-14T19:55:01",41,"Могго\n\nТот хрустнул шеей и почесал затылок\n\n--- А к чему спрашиваешь то? Угостить хочешь? Если да, то я только по вечерам пью. Как все, после работы",115090,null],[115092,"2026-07-14T19:55:49",0,"—настоящий авантюрист могго \n—пьет пива при любой возможности",115091,null],[115093,"2026-07-14T19:56:15",0,"//где остальные?",114768,null],[115095,"2026-07-14T19:59:15",41,"Могго\n\n--- Ну пей, кто тебе батька? Я пастух, и я счастлив. Кажется ваш рогатый парень хочет что-то узнать. Я, Как видите, одним глазом смотрю на вас - другим на коз. Но если хотите узнать \"что-то интересное\", то лучше поговорите с Сциллой - гадалкой нашей. \n\nОт скуки Могго оперся на палку руками, а сверху положил голову",115092,null],[115096,"2026-07-14T20:01:19",0,"—могго я чую в тебе дух авантюриста\n—нам нужно выпить могго",115095,null],[115097,"2026-07-14T20:02:37",41,"Могго\n\n--- Хорошо. Как закончите ваши детективные игры, с удовольствием выпью с вами",114768,null],[115098,"2026-07-14T20:03:06",0,"—договорились могго",114768,null],[115100,"2026-07-14T20:03:45",0,"—как нам попасть к гадалке могго?",114768,null],[115102,"2026-07-14T20:04:45",41,"Могго \n\n--- Ну у неё там шатер, идолы, вонь всякая. Узнаете, не ошибетесь.",114768,null],[115106,"2026-07-14T20:06:00",41,"@Jak_Zak @Xaosick  .",114768,null],[115110,"2026-07-14T20:07:49",32,"(хрип зомби) геаеагае\nУ а если серьезно то я тоже телефон включил",114768,null],[115117,"2026-07-14T20:20:48",42,"// я тут. Извиняюсь менталка убилась довольно сильно",114768,null],[115118,"2026-07-14T20:22:05",42,"— Ну чего же мы стоим, потопали туды\n°весело потопал к месту назначения°",114768,null],[115119,"2026-07-14T20:22:33",0,"-ну пошли",114768,null],[115120,"2026-07-14T20:22:43",0,"Иду за ним*",114768,null],[115123,"2026-07-14T20:26:07",42,"// извиняюсь в заранее если пропаду. Состояние не то чтобы обыгрывать хорошего",114768,null],[115136,"2026-07-14T20:51:56",41,"( так, я только вернулась домой. Ща отдышусь и продолжим",114768,null],[115165,"2026-07-14T21:03:14",32,"/Да я тоже тут но я устал",114768,null],[115398,"2026-07-14T22:17:25",41,"Давайте завтра нормально проведем, сори. Я с утра активнее буду",114768,null],[115782,"2026-07-15T13:15:35",41,"Заходя в деревню вы видите вполне обычную суету, человеческая женщина ловит курицу с кинжалом в зубах, парни гномы несут бедоны молока, снова человеческие дети играют в игру, но их лиц вы заметить не успеваете. \n\nПодходя все ближе к шатру вы уже слышите запах засушенных трав и благовоний. Приоткрывая входной занавес, вас встречает протяжное мяуканье под нос. \n\nЖенщина табакси с гладкой черной шерсткой мотает блестящий клубок на подушечке как волшебный - стеклянный шар. \n\nКак только вы подходите ближе или пытаетесь окликнуть её, она в мгновение открывает свои желтые глаза.",114768,null],[115784,"2026-07-15T13:18:23",41,"@tochhkatochka @Jak_Zak @Xaosick",114768,null],[115791,"2026-07-15T13:22:55",42,"// тута",114768,null],[115798,"2026-07-15T13:26:15",42,"°вдыхает полной грудью этот запах, вспоминая времена когда он помогал прокажëнным с помощью трав°\n— Запах такой родной и уютный! Ой.. Прекрасная миледи разрешите посетить ваш шатëр?",115782,null],[115805,"2026-07-15T13:31:49",32,"//Я могу кинуть соблазнение?",115783,null],[116001,"2026-07-15T15:49:30",42,"// для начала кидай спас соблазнения от Люми",115805,null],[116091,"2026-07-15T16:45:31",32,"/roll 2d20\nЗнамения",116001,null],[116093,"2026-07-15T16:45:51",32,"/roll d20+3\nСпас",116001,null],[116132,"2026-07-15T17:01:46",42,"// ты щас рыцръ так что в пролëте)",114768,null],[116190,"2026-07-15T17:40:02",42,"/roll 1d20 +5 а ну давай, если выйграшь будешь гладить Люми лежачего на твоих коленках",114768,null],[116205,"2026-07-15T17:44:12",32,"//Значит соблазнил",116191,null],[116240,"2026-07-15T18:08:11",42,"// всë. Будешь гладить Люми на своих коленях",116205,null],[116660,"2026-07-15T20:00:10",42,"// @sweetkittywitch будет сегодня игра?",114768,null],[116665,"2026-07-15T20:00:53",41,"( жду третьего чела точку",116660,null],[116671,"2026-07-15T20:01:28",41,"( я чет не поняла, что вы кидали друг другу?",114768,null],[116715,"2026-07-15T20:07:08",42,"// на то, будет ли рыцарь гладить Люми пока голова тифлинга коленях или нет",116671,null],[116723,"2026-07-15T20:07:54",41,"( эх",114768,null],[116753,"2026-07-15T20:12:15",42,"// @Xaosick @tochhkatochka вы тут?",114768,null],[116758,"2026-07-15T20:13:19",0,"Да",114768,null],[116762,"2026-07-15T20:14:40",42,"// остался Артур и всë",114768,null],[116805,"2026-07-15T20:22:38",32,"//у меня интернет упал и грузит все по пол часа и то только молитвами",114768,null],[116838,"2026-07-15T20:30:15",41,"( тебе нечего сказать?",116758,null],[116857,"2026-07-15T20:32:32",42,"// ладно.. Только ради тебя отрекусь от Сатаны и буду молиться на Интернет тебе",116805,null],[116859,"2026-07-15T20:32:52",0,"—Тише едешь — дальше будешь. Громче едешь — веселее будешь. Но недолго",114768,null],[116883,"2026-07-15T20:38:57",42,"— муудроо. Оооочень мудро. Но лучше я сгнию чем тихо ехать\n°кусает свой палец обдумывая ответ и передумал°",114768,null],[117008,"2026-07-15T21:16:40",41,"Мурри - Гадалка\n\n— Ммммр~~~ Я вижу ко мне по велению звезд пожаловали три далёких путника~~~ Какова же ваша цель? Расскажите мне, о-о-о, расскажите мне ! \n\nОна вновь начала вертеть лапками блестящий клубок",114768,null],[117013,"2026-07-15T21:18:08",42,"— Ой, ну чтобы не запамятоваться и лишнего не сказать прекрасная леди, вот\n°отдал ей контракт достав из своей сумки°",117008,null],[117023,"2026-07-15T21:25:46",41,"Взглянув одним золотым глазом в контракт, она отодвнула его обратно в сторону тифлинга. \n\n— О-о-о-о-о, звезды! Я вижу, да, я вижу! Ммммр~~~ Значит звезды сказали мне, что вас ведёт дорога приключений мрррр~~~ Вы ищете тех, кого забррррал дремучий лес. О-о-о, молодые путники. Я вижу ваше будущее! С кого бы мне начать? Вот! \n\nЕё коготок указал на молодого тифлинга\n\n— Я вижу , что душа твоя поет, да не просто поет, а жаждет любви! Любви бескорыстной и верной, как к самому себе. Четвероногий друг поможет тебе в пути, если позволишь ему ты! \n\nЕё золотые глаза скользнули на барда\n\n— А ты у нас мудрррр~ и умен, при хозяйстве человек. Но вижу в сердце твоем одиночество по женскому теплу, найти ту, кому так же одиноко~~~ \n\nПоследний коготочек свякнул по доспехам драконьего рыцаря\n\n— Герой, героем будешь. Устроишь званый ужин, полный мяса , вкусного мяса ~~~",114768,null],[117033,"2026-07-15T21:29:21",42,"— Ого!\n°схватился за свои щëки и сделал лицо удивления°\n— Спасибо большое прекрасная миледи. Пускай ваша жизнь будет сплошной улыбкой и умиротворением в душе!! \n°улыбнулся тифлинг очень ярко ей°",114768,null],[117036,"2026-07-15T21:31:40",0,"—один мудрец поведал мне однажды свой разговор\n—Гадалка сказала, видит смерть. Он сказал: \"Правильно видишь. Она за твоей спиной стоит и ждёт, пока ты цену назовёшь",117023,null],[117200,"2026-07-15T22:05:45",41,"( так, примем ещё игрока? Он третьего уровня, но я вас на третий быстро подниму",114768,null],[117240,"2026-07-15T22:15:02",41,"( я впишу игрока после гадалки",114768,null],[117242,"2026-07-15T22:15:10",41,"@Xaosick жду ответ",114768,null],[117521,"2026-07-15T23:00:24",41,"@Xaosick кхм",114768,null],[117608,"2026-07-15T23:19:00",32,"-Ха-ха-ха. Я конечно не мудр но вижу что сказать обо мне можно было и больше. Магией 4 круга вы леди точно не владеете",117023,null],[117609,"2026-07-15T23:19:28",32,"Но так и быть будет вам пир",114768,null],[117612,"2026-07-15T23:20:16",32,"(плазмоид просто развлекался так как быть героем не хотел ибо герой бывает только в учебнике истории или как памятник)",114768,null],[124262,"2026-07-19T16:43:02",41,"( Я сегодня готова вести с этого момента. Поставьте реакцие под это сообщение, если готовы",114768,null],[124263,"2026-07-19T16:43:21",41,"@tochhkatochka @Jak_Zak @Xaosick @Farkanis",114768,null],[124264,"2026-07-19T16:47:57",32,"//через час буду готов",114768,null],[124265,"2026-07-19T16:48:39",52,"/ я уже завтра отпишусь",114768,null],[124266,"2026-07-19T16:49:03",41,"Мурри\n\n— Смерть это вопрос мрррр~ времени~ \n\nС немного нервным мурчанием произнесла гадалка. \n\n— Надеюсь вы получили ответ на свой вопрос ~",117036,null],[124271,"2026-07-19T17:00:34",42,"// с этого момента готов играть за малыша Люми",114768,null],[124281,"2026-07-19T17:12:09",41,"( Сеню завтра впишу, сегодня можем доиграть",114768,null],[124292,"2026-07-19T17:13:54",42,"// оке, Щас будет ультралюбовь и ультразабота от Люми",114768,null],[124293,"2026-07-19T17:15:01",41,"( интересно, мне стоит им говорить, что от гадалки они ничего важного не узнали ?",114768,null],[124421,"2026-07-19T18:21:41",42,"// готовы же все? Если да. Я тоже готов если че",114768,null],[124422,"2026-07-19T18:24:02",41,"@tochhkatochka @Xaosick",124266,null],[124429,"2026-07-19T18:41:06",0,"—хорошо где у вас старейшина?",124266,null],[124432,"2026-07-19T19:03:16",32,"(несмотря на низкую мудрость даже рыцарь это заметил)\n//Я тут",124293,null],[124433,"2026-07-19T19:04:50",42,"— Друууузьяяяшки\n°потянулся со своей вечной и беззаботной улыбкой°\n— Ааа-аах.. А в чëм суть задания? Я просто размечтался когда увидел награду",114768,null],[124434,"2026-07-19T19:05:19",0,"—не знаю",114768,null],[124436,"2026-07-19T19:07:22",42,"— а вы сер рыцарь знаете? Простите такого глупышку как я\n°легонечко стукнул по макушке себя кулачком и высунул язык показывая свою дурашливость°",114768,null],[124437,"2026-07-19T19:09:42",32,"-Люди исчезли в лесу как и команда поисковиков. Задание расследовать куда делись и дополнительная награда за выведение выживших",124436,null],[124439,"2026-07-19T19:10:03",32,"(спокойно и даже повторив акценты с листовки плазмоид)",114768,null],[124441,"2026-07-19T19:14:12",42,"— О как. Спаааасииибооо большое мой стальной друг\n°обняц и на руке плазмоида появилась ленточка дружбы с именем \"Люми\", как и у люми с именем \"ревелон\" (Ободрябщая связь)°",114768,null],[124442,"2026-07-19T19:14:37",41,"Мурри \n\n--- О, так вы ищите старейшину. Обычно ко мне за этим не приходят)  Я рассказываю Что-то стоящее, а не показываю дорогу. Что ж, чаще всего Старейшина молится возле алтаря \"Проводительницы Наму\". Сегодня как раз её день",114768,null],[124443,"2026-07-19T19:18:19",0,"——А где алтарь?",114768,null],[124444,"2026-07-19T19:19:11",41,"Мурри\n\n--- На выходе из деревни в сторону леса. Это на запад)",114768,null],[124446,"2026-07-19T19:20:42",0,"Иду к алтарю и прощаюсь с гадалкой \n—пока пока",114768,null],[124447,"2026-07-19T19:25:22",42,"— до свидания прекрасная леди!! \n°уходит за мудрецом махая руками прекрасной Миледи°",114768,null],[124448,"2026-07-19T19:25:43",41,"Мурри\n\n--- Пока, герои)",114768,null],[124449,"2026-07-19T19:27:46",41,"/r d20+3 соблазнение от Мурри",114768,null],[124451,"2026-07-19T19:27:52",41,"( мех",114768,null],[124452,"2026-07-19T19:28:36",0,"На кого//?",124450,null],[124453,"2026-07-19T19:28:37",41,"( загрузка локации пошли",114768,null],[124454,"2026-07-19T19:28:44",41,"( на всех",124452,null],[124455,"2026-07-19T19:29:45",42,"— Спасибо большое красавица, всего вам наилучшего!) \n°сделал прощальный воздушный поцелуй обеими ладонями°",124448,null],[124456,"2026-07-19T19:29:56",42,"// ответно кину соблазнение?)",114768,null],[124457,"2026-07-19T19:31:20",41,"( давай :0",114768,null],[124458,"2026-07-19T19:31:37",42,"/roll 1d20 +5",114768,null],[124460,"2026-07-19T19:32:27",41,"Её хвост слегка задрожал, но она его спрятала. При этом как ни в чем не бывало смотря на вас",114768,null],[124462,"2026-07-19T19:34:42",41,"( в следующий раз она гадает ему на суженую: Я вижу девушку....кхм, с золотыми глазами....брюнетка, может у неё много волос, но это совсем не проблема~",114768,null],[124463,"2026-07-19T19:36:27",42,"// не зря есть церемония. Можно и на свадьбе быть и женихом и пастырем. Халявные +2 кд на 7 дней будут приятны как такая суженная ;3",124462,null],[124465,"2026-07-19T19:45:03",41,"Подходя к западному выходу, вы видите следующую картину. \n\nНа поляне огражденное стоит чучело...женщины? \n\nВокруг стоят люди, обсуждают что-то. Кто-то поёт, кто-то молится. \n\nВ поисках старейшины вы пытаетесь прикинуть старого мужчину и находите нескольких. Одеты они весьма ожнообразно, не выдавая кто из них настоящий",114768,null],[124466,"2026-07-19T19:49:48",0,"—мы хотим поговорить со старейшиной",114768,null],[124467,"2026-07-19T19:50:48",41,"( кому они это говорят  ?",114768,null],[124468,"2026-07-19T19:51:42",0,"К ближайшему //",114768,null],[124469,"2026-07-19T19:54:06",42,"°поëт вместе с певцами с искренней верой в слова песни и полная добра и безмятежности его голоса°",114768,null],[124470,"2026-07-19T19:54:17",42,"/roll 1d20 +5 выступление",114768,null],[124472,"2026-07-19T19:54:19",41,"Ближайший к тебе полурослик в облачении для пасечников, видимо было лень снять? \n\n--- П-п-привет....в-в-вам к старине Гифлию значит? Сейчас он речь произнесет и поговорит с вами...",114768,null],[124473,"2026-07-19T19:54:41",42,"// не знает слов и фальшивит)",124471,null],[124474,"2026-07-19T19:54:45",0,"—хорошо жду",114768,null],[124476,"2026-07-19T19:58:31",41,"Ты очень старательно слушал и подражал их песне. Однако некоторые строки песни тебя не прикрыто удивляли, от чего ты терял темп. Что-то вроде. \n\n\"В чащобе ветви счёт ведут —\n\nКто вышел, тот уже не тут.\n\nНа пне алеет новый след —\n\nЛес взял своё, сказав в ответ.\nМы лишь солома на ветру,\n\nНас ломит страх к чужому костру.\n\nПока огонь поёт весной —\n\nНе он насытится золой.\"",124469,null],[124477,"2026-07-19T20:03:18",41,"( мне продолжить или будут комментарии?",114768,null],[124478,"2026-07-19T20:06:23",42,"// продолжай",114768,null],[124483,"2026-07-19T20:07:18",0,"Начинаю петь вместе с ними *",114768,null],[124484,"2026-07-19T20:07:32",0,"/r d20+5 выступление",114768,null],[124490,"2026-07-19T20:09:00",41,"Один гоблин кидает в рот яблоко второму первцу",114768,null],[124491,"2026-07-19T20:09:06",41,"/r d20+4",114768,null],[124493,"2026-07-19T20:10:05",41,"@tochhkatochka в тебя",114768,null],[124494,"2026-07-19T20:10:43",0,"Неприятно*",114768,null],[124495,"2026-07-19T20:11:19",0,"Иду к тому боблину *",114768,null],[124496,"2026-07-19T20:11:48",41,"Боблин убегает \n\nЕго лениво окликивает какой-то дед",114768,null],[124498,"2026-07-19T20:12:30",0,"Бегу за ним*",114768,null],[124499,"2026-07-19T20:12:54",41,"( атлетика на поимку против его акробатики",114768,null],[124501,"2026-07-19T20:14:20",0,"/r d20-1",114768,null],[124503,"2026-07-19T20:17:08",42,"— АААА ЛОВИ КАРАТЫШКУ\n°прыгает и тоже хочет споймать воспринимая это как игра°",114768,null],[124505,"2026-07-19T20:18:01",42,"/roll 1d20 -1",114768,null],[124507,"2026-07-19T20:18:31",42,"— Апхаха. Ловкий малый. Не споймали",114768,null],[124510,"2026-07-19T20:30:22",41,"/r d20+4 ради вежливости кину",114768,null],[124512,"2026-07-19T20:32:28",41,"Вы бежите за гоблином, он оборачивается сначала на волосатого черта, потом на лысого черта. \n\nРжет и в момент оставляет облачкло дыма вместо себя. \n\nГоспода стукаются лбами и над их.головой летают птички",114768,null],[124514,"2026-07-19T20:35:06",0,"—ух гоблин ну погоди",114768,null],[124519,"2026-07-19T20:41:58",32,"-Ребята уважте местный праздник, ведите себя прилично.\n(Рыцарь был сама невозмутимость) Сидел в стороне и не мешал всем веселится хотя строки из песни явно давали понять что тут поклонение какому-то не хорошему существу",114768,null],[124520,"2026-07-19T20:43:30",42,"°встал, отряхнулся и подошëл к плазмоиду. Встал по стойке смирно и выполнил воинское приветствие и высунул язык игриво улыбаясь°\n— ййййй-Есть сер!",114768,null],[124521,"2026-07-19T20:48:36",32,"(спокойно кивнул и жестом руки предложил присесть. Слушая местные песенки)",124520,null],[124522,"2026-07-19T20:49:02",0,"Сожусь *",114768,null],[124523,"2026-07-19T20:49:53",42,"°сел рядом и виляет ногами туда сюда. А браслет дружбы загорелся ярче на руке плазмоида°",114768,null],[124524,"2026-07-19T20:50:40",42,"// короче это благословение на обоих до тех пор пока мне не сломают концентрацию и до долгого отдыха. + 1д4 ко всему раз за ход",114768,null],[124525,"2026-07-19T20:54:27",41,"Плазмоид, оставшийся один на ритуале может видеть, как над чучелом вспарил мужчина с одним ангельским крылом бронзового цвета. Местами седая борода, усталый взгляд и такие же посидевшие волосы заплетеные в низкий пучок. \n\nИз разговоров людей рыцарь слышит фразу в духе \n\n\"Тихо, старейшина говорит\" \n\nОт чего становится понятно. Старейшина не добрый дедушка, он аасимар. Один из немногих сохранившихся в этом мире без божественного \n\nНо герои успели вовремя вернуться и услышать всю речь \n\nСтарейшина:.\n\n--- Мы собрались здесь чтоб воздать лесной проводнице и её друзьям дары в знак нашей преданности. \n\nПочему-то даже с такого расстояния можно было видеть искреннюю печаль на его лице\n\n--- Ваш страх можно понять, мои друзья, но нельзя оправдать. Что бы вы не слышали от тех чужеземцев...\n\nОн выдержал паузу, наполняя её злобой и гневом\n\n--- Они хотели обмануть нас! Лесные духи век жили с нами бок о бок в мире! Они не могли предать нас, ведь ложь - лишь человеческий порок! \n\nВ руке мужчины загорелся факел, быстро, но не магически\n\n--- Я сожгу чучело Наму и зола разлетится по лесу! Не давайте волю грязным мыслям! Пусть духи леса слышат нашу преданность и защиту!",114768,null],[124526,"2026-07-19T20:55:26",32,"//я занят и работаю сейчас",114768,null],[124528,"2026-07-19T20:58:47",0,"—Нож тупой? Значит, ты тупой. Точи, пока не увидишь в лезвии своё будущее\n*все получают 6 временых хп*",114768,null],[124529,"2026-07-19T21:00:31",42,"— Как вдооооохновляюще. Запомню эти слова для своих последователей\n°сел и дальше слушает мудреца°",114768,null],[124533,"2026-07-19T21:38:33",32,"//то же вдохновляющий лидер?",124528,null],[124534,"2026-07-19T21:38:45",42,"// и у меня",124533,null],[124536,"2026-07-19T21:39:32",42,"// я Бог опостал, обязан вдохновлять своих последователей",114768,null],[124537,"2026-07-19T21:39:50",32,"(тихо шопотом товарищам) -почему мне это нравится все меньше и меньше?",124525,null],[124538,"2026-07-19T21:40:46",42,"— Не знаю. А может потому что.. \n°тык в нос°\n— ты вредина? И не нравлиш? Сер рыцарь",124537,null],[124540,"2026-07-19T21:42:49",32,"-Прошу уважаемый не быть настолько фамильярно со мною. (Слегка волнуясь сказал Ривелон) Нет не из-за того что я кто-то там а потому что... В общем не важно",114768,null],[124609,"2026-07-19T22:19:27",42,"— Даааа нееее пааарься. Будь спокоен. Я же тебя не тащу в пастель, просто ты выглядишь надëжным и это мне нравится в тебе\n°улыбка уже поменяла на ехидную эмоцию°",124540,null],[125447,"2026-07-20T15:58:12",41,"Старейшина спустился и зажег подол чучела, позволяя пламени подниматься вверх \n\n--- Помолимся о прощении. Это лучшее, что мы можем сделать! \n\n(желаете кинуть внимание или просто слушаете старейшину?)",114768,null],[125448,"2026-07-20T15:58:43",41,"@Jak_Zak @tochhkatochka @Xaosick @Farkanis\n\nСобираю",114768,null],[125455,"2026-07-20T15:59:26",52,"/ я тут жду когда меня введут)",114768,null],[125462,"2026-07-20T16:00:30",42,"// я тут",114768,null],[125463,"2026-07-20T16:00:48",0,"//Где-то через 30 минут смогу давайте пока что без меня",114768,null],[125476,"2026-07-20T16:09:00",32,"/я тоже тут но ещё занят",114768,null],[125495,"2026-07-20T16:24:10",41,"( мой пост отписан. Жду ваших действий",114768,null],[125538,"2026-07-20T16:37:25",0,"Кидаю//",125447,null],[125540,"2026-07-20T16:37:37",0,"Проницательность или внимание//?",114768,null],[125546,"2026-07-20T16:38:45",0,"/r d20+4",114768,null],[125603,"2026-07-20T17:09:00",42,"/roll 1d20 +6 внимательность",125447,null],[125605,"2026-07-20T17:09:29",42,"/roll 1d4",114768,null],[125607,"2026-07-20T17:09:34",42,"//19 внимательности. Забываю о приколе с связью ободряющей",114768,null],[125608,"2026-07-20T17:15:32",41,"Внимание ?",125547,null],[125609,"2026-07-20T17:30:04",0,"Ага //",125608,null],[127094,"2026-07-21T17:12:23",52,"/🫠",114768,null],[127104,"2026-07-21T17:16:26",41,"( сегодня мне уже не так плохо ура",114768,null],[127113,"2026-07-21T17:18:04",42,"// Ура победа",114768,null],[127115,"2026-07-21T17:18:43",42,"// надеюсь сегодня или завтра фамильярный Люми поиграется",114768,null],[131139,"2026-07-27T19:24:53",41,"( Жака исключен с квеста, скоро продолжим или квест закончится",114768,null],[131157,"2026-07-27T19:34:51",41,"Я не буду вести квест убийце",114768,null],[131182,"2026-07-27T19:52:10",42,"// пипяо.. Ну ладно , _,",114768,null],[132451,"2026-07-30T12:26:16",41,"@elsio28 ты вроде хотел сюда? Можешь?",114768,null],[132467,"2026-07-30T13:28:55",5,"// да. На К'варсио",132451,null],[132494,"2026-07-30T14:49:08",5,"// можно вписать, что грунг стоит с толпой глазеет на ритуал",114768,null],[132496,"2026-07-30T15:07:32",41,"( оке, после собеседования отпишу",114768,null],[134209,"2026-08-01T14:26:42",41,"Однако вы быстро замечаете, что большинство собравшихся почти не слушает старейшину.\nОдни, опустив головы, тихо молятся лесным духам, прося у них прощения. Другие смотрят на старейшину с явным недоверием. А некоторые даже не пытаются скрыть своих разговоров.\n\nСамый младший из группы подростков презрительно усмехнулся:\n\n— Совсем старик из ума выжил. Уже сам верит в собственную хрень.\n\nПарень постарше лишь пожал плечами:\n\n— А разве он когда-нибудь не верил?\n\nСтоявшая рядом девушка раздражённо цокнула языком.\n\n— Да ну вас... Мне родители всю жизнь рассказывали, что Наму — просто детская сказка. Я в детстве вообще не боялась в этот лес ходить.",114768,null],[134210,"2026-08-01T14:27:12",5,"// где я?",114768,null],[134211,"2026-08-01T14:27:22",41,"В толпе",134210,null],[134220,"2026-08-01T14:33:54",5,"Невысокий красный грунг стоит в толпе и смотрит на разгорающееся пламя. Жар уже неприятно ощущается на чувствительной коже.\n\nК'варсио глазеет на аасимара и ищет ответ на простой вопрос: добрый это ритуал или злой?",134209,null],[134222,"2026-08-01T14:34:16",5,"// так я могу кинуть монетку) или религию",114768,null],[134223,"2026-08-01T14:34:23",41,"( история или магия",114768,null],[134225,"2026-08-01T14:35:04",5,"/r +1",114768,null],[134230,"2026-08-01T14:36:31",5,"// ничего, знания всё равно бесполезны",114768,null],[134234,"2026-08-01T14:37:30",41,"Языки пламени неприятно расходятся по сену. Для грунга, что природа связана с лесами и болотами, подобная картина выглядит крайне зловеще. \n\nК сожалению, единственный вывод к которому приходит внимательная лягушка. Что зола летит в сторону леса. Хорошо это или плохо? Неизвестно",114768,null],[134250,"2026-08-01T14:42:11",5,"Зола выглядит неприятно, но лесу она не повредит. \n\nГрунг не может понять, что тут происходит и решает обратиться к своей покровительнице — архифее. Она наверняка подскажет, кто тут хороший.\n\nК'варсио касается медальона на шее и тот отвечает голосом архифеи (как происходило всегда):\n\"Обещаю... Всегда...\"",114768,null],[134251,"2026-08-01T14:42:20",5,"/r чистый рандом",114768,null],[134490,"2026-08-01T16:12:19",41,"Стоит лягушонку моргнуть, как он оказывается в сером пространстве, лишённом людей. Кружащаяся вокруг зола складывается в очертания леса, ограждения вокруг чучела и самого соломенного образа девушки Наму.\n\nУ куклы горят глаза — ровным белым призрачным светом.\n\nПозади ощущается приятный летний бриз. Не оборачиваясь, грунг чувствует, как его шею нежно обнимают две тонкие руки.\n\n— Здравствуй, мой принц-лягушонок.\n\nРаздаётся высокий голос, мелодичный, словно весенний дождь.\n\nОн не видел, как фея склонила голову, но чувствовал её взгляд, устремлённый на соломенное чучело.\n\n— Ну что за безвкусица... Немного украсить — и можно даже не сжигать~\n\nНарисованная девушка вновь перевела взгляд на лягушонка.\n\n— Ты ведь хотел спросить меня, кто здесь хороший?\n\nФея тихо рассмеялась.\n\n— Но лишь в нашей стране всё делят на добрых и злых. В этом мире, полном теней и войн, всё куда сложнее...",114768,null],[134525,"2026-08-01T16:22:43",5,"— Здравствуйте, моя кваспожа! \n\nСчастливый лягушонок повернул голову, пытаясь рассмотреть архифею.\n\n— Я знал, что квы ответите на мою просьбу! Ква!\n\nГрунг отвёл взгляд от прекрасной феи и посмотрел на светящиеся глаза куклы.\n\n— Старик сжигает чучело, кворит, что квак надо! Огонь сушит кожу, неприятвно! Но вдруг он хороший? Всё так сложно, госпожа... Как мне разобраться в этом мире?",114768,null],[134611,"2026-08-01T16:46:17",41,"Повернув голову, он смог увидеть профиль девушки, будто сошедшей с незавершённого акварельного эскиза. Её волосы струились, словно живые мазки краски, а крылья, напоминавшие застывшие капли воды, легко удерживали фею в воздухе. На её милом лице играла тёплая улыбка.\n\n— Ты умный маленький лягушонок. Уже потому, что ищешь справедливость, а не выгоду. Но мир редко делится на хороших и плохих. Почти всё живое здесь измеряют ценой... и целью. Тебе самому предстоит решить, стоит ли заплаченная цена того, что получится в итоге.\n\nЗаметив недоумённый взгляд грунга, она тихо хихикнула.\n\n— Но я откликнулась не только затем, чтобы говорить загадками~\n\nФея мягко отвела взгляд в сторону леса.\n\n— Когда ты позвал меня, я увидела чащу, где духи потеряли свою цену. Словно сама жизнь перестала считать их нужными... или они сами забыли, ради чего продолжают существовать.\n\nОтпустив принца-лягушонка, Веренестра легко развела руками, и вокруг неё закружились крошечные лепестки.\n\n— Сходи туда... но не один. Позволь другим самим решить, кто разделит с тобой этот путь. А когда вы услышите каждого, кто оказался частью этой истории, добро само найдёт дорогу к тебе.\n\nИ, прикрыв глаза, она почти пропела, словно вместе с ветром:\n\n\"Не тот мудрец, кто суд вершит,\nНе тот, кто первым скажет: «Виноват».\nЛишь тот найдёт тропинку средь ракит,\nКто выслушает всех... и не посмотрит вспять.\"\n\n\"У каждой боли — собственная тень,\nУ каждой жертвы — собственная быль.\nИ если сердце не осудит в этот день,\nТо вслед за ним добро рассыплет пыль.\"\n\nМгновенное - случайное смыкание глаз принца и видение вновь возвращает его к лесу, чучелу и народу",114768,null],[134632,"2026-08-01T16:51:55",5,"Грунг слушал архифею и запоминал её слова.\n\n— Спасибо, кваспожа!\n\nК'варсио моргнул и видение рассеялось.\n\n— Ква! Где вы? Я не успел узнать ваше имя, госпожа!",114768,null],[134653,"2026-08-01T16:56:52",5,"Лягушонок посмотрел на стоящих вокруг людей. И сказал так, чтобы его слышали остальные.\n\n— Духи в лесу есть, я знаю! Но они потерялись. Надо найти их и указать путь к добру! Ква!",134209,null],[134727,"2026-08-01T17:14:04",41,"Несколько человек на него смотрят с очень конкретным выражением лица \"Че?\" \n\nПосле продолжают молитвы",114768,null],[134729,"2026-08-01T17:14:19",41,"А вы? @tochhkatochka @Xaosick",134653,null],[134790,"2026-08-01T17:32:05",32,"//а перс Жаки вроде на кресте башни любви.",134729,null],[134799,"2026-08-01T17:33:27",41,"Я его исключила",134790,null],[134802,"2026-08-01T17:33:53",32,"//а чего так?",134799,null],[134817,"2026-08-01T17:36:27",41,".",114768,null],[134818,"2026-08-01T17:36:27",41,"( Жака исключен с квеста, скоро продолжим или квест закончится",114768,null],[134819,"2026-08-01T17:36:27",41,"Я не буду вести квест убийце",114768,null],[134824,"2026-08-01T17:36:43",41,"Причина тут",134802,null],[134827,"2026-08-01T17:37:57",32,"Ну ок я тогда тож ушел",114768,null],[134829,"2026-08-01T17:38:07",41,"Ладно",134827,null],[134876,"2026-08-01T17:52:26",0,"В смысле убийце?",134819,null],[134880,"2026-08-01T17:53:28",41,"Он сказал, что он убийца. Достаточно сказал, чтоб я ему не вела",134876,null],[134896,"2026-08-01T17:59:59",0,"// ээээ что",134880,null],[134898,"2026-08-01T18:00:29",41,"Буквально",134896,null],[134903,"2026-08-01T18:01:17",0,"// где и как",134898,null],[134904,"2026-08-01T18:02:17",41,"На войне. Моих людей",134903,null],[134907,"2026-08-01T18:02:46",41,"А может и своих, он не уточнял",114768,null],[134924,"2026-08-01T18:06:09",41,"Это всё?",114768,null],[134941,"2026-08-01T18:11:48",0,"В днд?",114768,null],[134942,"2026-08-01T18:12:04",0,"//В какой-то игре?",114768,null],[134948,"2026-08-01T18:12:42",41,"( нет. В настоящей войне",134942,null],[134951,"2026-08-01T18:13:39",0,"// это же шутка",134948,null],[134953,"2026-08-01T18:14:09",41,"Не шутка",134951,null],[134956,"2026-08-01T18:16:10",0,"//да ну наиг я ливаю с квеста",114768,null],[134957,"2026-08-01T18:16:25",41,"Хорошо",134956,null],[134959,"2026-08-01T18:17:17",41,"@elsio28 к тебе никто не прислушался. Тебе Остается идти одному.",114768,null],[134969,"2026-08-01T18:20:27",5,"К'варсио громко квакал, созывая людей идти в лес за духами. Но, похоже, никто не прислушался.",114768,null],[134971,"2026-08-01T18:22:25",5,"Грунг несколькоими высокими прыжками выбрался из толпы и неторопливо попрыгал в лес",114768,null],[134972,"2026-08-01T18:23:01",5,"Как следопыт, он осматривает следы, изучает чащобу. Ищет путь в самое сердце леса",114768,null],[135747,"2026-08-02T22:30:23",41,"( завтра начну нормально",114768,null],[135748,"2026-08-02T22:30:35",41,"( сегодня с художниками тусила",114768,null],[135751,"2026-08-02T22:37:55",5,"// молодец, жду",135748,null],[153158,"2026-08-11T16:30:43",41,"( так, я тут",114768,null],[153160,"2026-08-11T16:30:59",41,"( можем продолжить сегодня вечером",114768,null],[153319,"2026-08-11T17:13:26",5,"// о неужели",114768,null],[153321,"2026-08-11T17:13:29",5,"// да попозже",114768,null],[154031,"2026-08-11T21:07:14",41,"Чаща казалась неестественно \"водянистой\", будто узоры листьев плыли по ветвям. Или то не узоры совсем?\n\nПродолжая свой путь, Принц замечает несколько сломанных веточек\n\n(внимание)",114768,null],[154035,"2026-08-11T21:08:05",5,"/r +3",114768,null],[154092,"2026-08-11T23:02:45",41,"Ты находишь очень много следов, но эти следы неправильные. Будто одна нога шла вперед, вторая назад. \n\nТак же обувь странная, как прямоугольник или мостик",114768,null],[154100,"2026-08-12T01:23:38",5,"Лягушонок наклонился, рассматривая следы.\n\n— Ноги в разные стороны. Всё так странно! Могут ли они принадлежать духам?\n\n К'варсио пошёл по этим следам, беспокойно оглядываясь",114768,null],[156863,"2026-08-12T20:18:30",41,"К’варсио шел вперед, позади него подобно плащу развивалась гнетущая атмосфера леса. Странные следы, отсутствие шума, будто его забрали эти странные деревья. \n\nНебольшой запах золы напоминал тебе про твою цель, как тут ты внезапно видишь… следы побольше. Огромные такие. \n\nИ обе ступни направлены вперед. Пойдешь ли ты по ним?",154100,null],[156873,"2026-08-12T20:19:58",5,"*смотрю, остались ли другие, неправильные следы*",156863,null],[156883,"2026-08-12T20:21:32",41,"Они запутались, кажется пропали",114768,null],[156893,"2026-08-12T20:23:21",5,"Грунг съеживается.\n\n— Эти следы такие большие. Как-то мне боязно!\n\nВсё же он идёт по ним, но теперь прячась и зыркая во все стороны",156883,null],[156897,"2026-08-12T20:24:08",41,"Приближаясь к следам он слышит тяжелое дыхание и сваливающийся ветки, будто они помешали пройти кому-то большому…",114768,null],[156898,"2026-08-12T20:24:16",41,"@Farkanis ваш выход",114768,null],[156993,"2026-08-12T20:47:59",52,"@sweetkittywitch чуть попозже отпишу ) ребенка укладываю )",114768,null],[157029,"2026-08-12T20:58:23",41,"Ов. Хорошо)",156993,null],[157775,"2026-08-13T09:02:17",52,"Тишина леса была нарушена не просто шумом, а ощущением присутствия чего-то, что здесь быть не должно. Те самые «неправильные» следы, которые так старательно изучали, внезапно слились в один массивный, размашистый путь.\nВнезапный, оглушительный треск валежника заставил все живое вокруг вздохнуть. Из густой тени, под аккомпанемент тяжелого, раздраженного дыхания, стремительно вынырнул огромный силуэт. Багбир не пытался спрятаться. Он просто перестал это делать, позволяя тени вокруг него «взорваться» и обнажить его мощную фигуру.\nОн стоял прямо впереди, окутанный легкой дымкой пепла, и его взгляд, холодный и пронзительный, заставил бы любого позабыть о том, что они искали.",114768,null],[158219,"2026-08-13T16:47:08",5,"Невысокий грунг позабыл о маскировке, увидев такую фигуру и подпрыгнул на месте, громко квакнув.\n\n— Ты ктво? Лесной дух? Я ищу лесных духов!",157775,null],[158352,"2026-08-13T17:43:17",52,"Гракх не шелохнулся. Багбир медленно перенес вес с одной ноги на другую, и земля под его массивной лапой едва заметно вздрогнула.\nНа вопрос лягушонка он ответил не сразу. Молчание затянулось, становясь почти осязаемым, давящим на уши. Гракх смотрел на маленькое существо сверху вниз, и в его взгляде не было ни злобы, ни дружелюбия - лишь бесконечная, свинцовая усталость.\n- Духов не ищут, - голос Гракха прозвучал низко, как камнепад где-то в горах. Он не кричал, но звук был настолько плотным, что казалось, его можно потрогать. - Духи сами находят тех, кто им мешает.\nОн на мгновение прикрыл глаза, словно пытаясь отогнать навязчивый запах золы, который преследовал его с тех пор, как исчезла Джени.\n- Ты слишком громкий, малявка. В этом лесу тишина - это жизнь. А ты... ты - приглашение к смерти.",114768,null],[158367,"2026-08-13T17:48:16",5,"— Не ищут? Значит я квашел не лесного духа.\n\nГрунг посмотрела багбира и услышал слова о смерти.\n\n— Сначала догони, убивца!\n\nК'варсио попрыгал в лес со всех лап.",114768,null],[158419,"2026-08-13T18:02:56",5,"// ыыы протестую, мастер",158413,null],[158424,"2026-08-13T18:04:12",52,"// ну так то мене вообще тебя смыслов ловить нет)) но я чтоб продвинуть знакомство решил отыграть так )",114768,null],[158427,"2026-08-13T18:05:02",41,"( ща ща ща, я ужинаю",114768,null],[158440,"2026-08-13T18:06:46",5,"// персонаж может поступать как хочет\nя протестую против нелогичности такой ловли",158424,null],[158447,"2026-08-13T18:07:37",52,"/я по лору знаком с этим лесом, ну и скорость у меня в 2 раза больше",114768,null],[158473,"2026-08-13T18:10:07",41,"( ща разберусь, не спорьте",114768,null],[158480,"2026-08-13T18:10:41",52,"/в целом пофиг, могу переписать что я в принципе не пошел за грунгом",114768,null],[158483,"2026-08-13T18:11:07",41,"( ну само появление я не вижу за гранью нарратива",114768,null],[158484,"2026-08-13T18:11:21",41,"( в другой ситуации я,бы попросила броски",114768,null],[158497,"2026-08-13T18:12:47",5,"// окей",114768,null],[158505,"2026-08-13T18:13:46",5,"— Опять ты! Чтво ты от меня хочешь? \n\nГрунг испуганно смотрит на багбира.",158413,null],[158514,"2026-08-13T18:14:57",41,"( ой, они знакомы:0",114768,null],[158515,"2026-08-13T18:15:22",5,"/ ?",158514,null],[158521,"2026-08-13T18:17:02",41,"( а, сори",114768,null],[158522,"2026-08-13T18:17:06",41,"( читаю",114768,null],[158836,"2026-08-13T19:07:17",5,"Лягушонок выглядит всё более напуганным. От беспокойства он негромко квакает.\n\n— Квакая Дженни? Квакой дом? Я пришел в деревню смотреть на сожжение чучела. Не знаю никвакой Дженни.\n\nУвидев позу багбира, Кварсио отпрыгнул на шаг.\n\n— И к ручью мне не надо. Мне вообще не в эту сторону. Я ищу духов в глубине леса!",158765,null],[159095,"2026-08-13T20:20:24",5,"— Ква... Если ты идёшь в глубь леса, то квожем идти вместе... Только не касайся меня своими ручищами!",114768,null],[159145,"2026-08-13T20:35:33",5,"К'варсио следует за ним на небольшом расстоянии",114768,null],[159146,"2026-08-13T20:35:39",52,"/ нужно на что-то кидать для продолжения сюжета ? @sweetkittywitch",114768,null],[159148,"2026-08-13T20:36:57",41,"( я бы попросила подождать пж",114768,null],[159150,"2026-08-13T20:37:06",41,"( ща продолжу",114768,null],[159212,"2026-08-13T22:52:31",41,"( у меня работа удалилась. Сори завтра продолжу",114768,null],[160518,"2026-08-14T20:28:42",52,"/ @sweetkittywitch 👀",114768,null],[160519,"2026-08-14T20:29:03",41,"( помню, готовлюсь читаю",114768,null],[160520,"2026-08-14T20:29:07",41,"В 21 начнем",114768,null],[160689,"2026-08-14T21:53:54",52,"/ @sweetkittywitch 👀",114768,null],[160696,"2026-08-14T21:58:27",41,"( сори, меня слегка затянуло в важную сцену. Сори",114768,null],[160738,"2026-08-14T23:33:22",41,"Лес не ответил сразу.\n\nГде-то в вышине один раз хрустнула ветка. Потом другая — уже дальше. Будто кто-то переступал с дерева на дерево, не касаясь земли.\n\nПод корнем тихо осыпалась земля. \n\nСледы, что ещё мгновение назад были отчётливыми, медленно затянуло мокрой листвой. Не ветром — лист ложился на лист сам собой, один за другим.\n\nИз чащи донёсся низкий, глухой шорох.\n\nНе голос. . .Не зверь.\n\nТак старые деревья шепчутся корнями, когда не хотят, чтобы человек понял их речь.\n\nГде-то справа коротко каркнула ворона.\n…\nЕй ответила вторая.\n\nПотом третья — уже совсем близко.\n\nИ между стволами проступило нечто похожее на тропу. Узкую, тёмную, заросшую мхом. Ни один след по ней не шёл.\n\nЛес будто показывал дорогу.\n\nИ будто ждал, кто первым решится по ней ступить.\n\n(Кто делает первый след?)",114768,null],[160746,"2026-08-15T00:14:26",5,"Услышав карканье ворон, К'варсио коснулся амулета и что-то тихо проквакал. Вскоре он смог понимать голоса птиц.\n\n// Разговор с животными\n\nГрунг прислушивается к голосу лесных зверей.",160738,null],[160750,"2026-08-15T00:18:27",41,"…«Другие Двулапые»\n\n«Не шумят» \n\n…«Опасные?» \n\n…«Не для нас» \n\n«…»\n\n       ╱╲       ╱╲\n     (  ◉ )       ( ◉  )\n   ╲︶╱     ╲︶╱\n  ︶╲╱︶︶╲╱︶\n\n𓅃「к̷а̷…」  𓅃「к̷а̷а̷?」\n\nТы перестал их понимать на ходу",160746,null],[160752,"2026-08-15T00:20:52",41,"( эта типа вороны нарисованы",114768,null],[160753,"2026-08-15T00:21:02",5,"— Странно, будто моя квагия испарилась\n\nЛюбопытный лягушонок первый попрыгал по тропе",114768,null],[160754,"2026-08-15T00:21:18",5,"/А, хд. Я подумал лицо лешего какого-то",160752,null],[160755,"2026-08-15T00:21:33",41,"( Как теперь развидеть ???",160754,null],[160756,"2026-08-15T00:21:53",41,"Ты чувствуешь, что касаешься плетения. Заклинание ещё действует",160753,null],[160757,"2026-08-15T00:21:53",5,"// а всё",160755,null],[160758,"2026-08-15T00:22:21",5,"— Неужели язык птиц... Поменялся? Как странно!",160756,null],[160761,"2026-08-15T00:25:02",41,"Впереди, за елями, трижды стукнуло дерево о дерево.\n\nТук.\n\nПауза.\n\nТук.\n\nТук.\n\nСтарый лесной знак. Так здесь звали друг друга те, кто не хотел оставлять голоса между деревьями.\n\nНо ответ пришёл не из чащи.\n\nИз-под земли.\n\nКорни едва заметно дрогнули, и в рыхлой земле показалась узкая полоса белого мха. Она тянулась от старого пня дальше, в сторону низины, где даже днём держался сумрак.\n\nНа мху лежало перо.\n\nЧёрное, длинное, мокрое от росы.\n\nА рядом — маленькая косточка, чистая до блеска.\n\nВетер прошёл по верхушкам елей, и лес будто вздохнул.\n\nИз низины крик. \n\nОдин раз.\n\nОчень далеко.\n\nНе ясно, животный или человеческий. Испуганный или кличущий",114768,null],[160767,"2026-08-15T00:30:34",5,"Грунг настороженно прислушивается.\n\n— Духи? Я пришёл проверить, в кварядке ли вы!\n\nОн подошёл к лежащим на мху перу и косточке.\n\n— Это квакие-то знаки?",114768,null],[160775,"2026-08-15T00:38:12",52,"Гракх не стал ждать. Он сам шагнул ближе к пню, опустился на корточки — тяжело, с хрустом — и протянул руку к перу и косточке.\n\nНе взял. Сначала просто посмотрел. Принюхался.\n\nПотом аккуратно коснулся пера кончиками пальцев — сухое, но влажное на ощупь, будто его только что окунули в росу. Косточка рядом — чистая, гладкая, без следов зубов или ножа.\n\nГракх поднял взгляд на тропу из белого мха, ведущую в низину. Потом снова посмотрел на свою руку.\n\n— Лес не оставляет вещей просто так, — пробормотал он себе под нос. — Но кто-то здесь был до нас. Свежий след.\n\nОн выпрямился, сжав перо в пальцах, и повертел его, рассматривая под разным углом. Чёрное. Длинное. Слишком большое для обычной вороны.\n\n— Кто-то специально это здесь положил, — сказал он уже громче, чтобы К'варсио слышал. — Или лес подсказывает, куда идти. Или заманивает.\n\nОн спрятал перо за пояс — не выкидывать, может пригодиться — и ещё раз окинул взглядом косточку. Не тронул.\n\n— Я иду в низину. Если хочешь — проверяй свои духи. Но я иду по следам живых.\n\nГракх развернулся и двинулся по мшистой тропе, держась ближе к теням деревьев. Его шаги стали тише — он перешёл на скрытность. Пальцы коснулись оружия на поясе.\n\nЛес снова вздохнул, и где-то вдалеке снова раздался тот же крик. Теперь чуть ближе.",114768,null],[160779,"2026-08-15T00:39:38",41,"( артефакты за меня не пиши пж(",114768,null],[160780,"2026-08-15T00:39:52",41,"( так, ладушки, кинь историю",114768,null],[160782,"2026-08-15T00:40:47",52,"/ так я не писал просто взял из твоего описания просто \n\nСейчас кину не помню сколько у меня там",114768,null],[160784,"2026-08-15T00:41:32",41,"( оке",114768,null],[160786,"2026-08-15T00:41:49",52,"/roll 1d20",114768,null],[160791,"2026-08-15T00:42:05",41,"( успех! )",114768,null],[160804,"2026-08-15T00:45:27",5,"— Духи не отвечают мне. Духи, ответьте!",160775,null],[160808,"2026-08-15T00:46:25",41,"Ты вспоминаешь свою дорогую приятельницу, которая любезно помогла тебе в деревне. \n\nИменно ей принадлежат эти косточка и перышко. \n\nКажется она хотела оставить вам какое-то послание",114768,null],[160830,"2026-08-15T00:52:18",41,"@Farkanis для тебя",114768,null],[160838,"2026-08-15T00:56:24",41,"( киньте скрытность",114768,null],[160839,"2026-08-15T00:56:47",52,"/ моя серьга както реагирует ? https://dnd.su/items/161-weapon-of-warning/",114768,null],[160841,"2026-08-15T00:57:53",52,"/roll 1d20 +5",114768,null],[160845,"2026-08-15T00:58:16",41,"Твоя серьга постоянно с этого момента слегка нагрета и вибрирует, но недостаточно чтоб бить тревогу",114768,null],[160852,"2026-08-15T01:02:02",52,"/видимо случайно нажал 2 раз",114768,null],[160855,"2026-08-15T01:04:39",5,"К'варсио двинулся за багбиром, но не особо прятался, да и доспех был неподходящий...",114768,null],[160856,"2026-08-15T01:04:48",5,"/r -d20+2",114768,null],[160858,"2026-08-15T01:05:14",41,"( утречком отпишу",114768,null],[160859,"2026-08-15T01:05:17",41,"( споки",114768,null],[160860,"2026-08-15T01:05:38",52,"/окей, спокойной ночи",114768,null],[160861,"2026-08-15T01:05:40",5,"/ спокойной",114768,null],[161159,"2026-08-15T11:59:36",52,"/ @sweetkittywitch 👀",114768,null],[161160,"2026-08-15T12:00:05",41,"( прив. Ща покушаю и продолжу",114768,null],[161183,"2026-08-15T12:10:27",52,"/ привет ) приятного аппетита)",114768,null],[161185,"2026-08-15T12:11:20",41,"( спасибо)",161183,null],[161986,"2026-08-15T19:02:59",52,"/ @sweetkittywitch 👀",114768,null],[161993,"2026-08-15T19:05:06",41,"( сори, мне все еще хреново",114768,null],[162810,"2026-08-16T22:04:35",52,"/ @sweetkittywitch 👀",114768,null],[162811,"2026-08-16T22:07:50",41,"( сори, сегодня снова работа. Завтра",114768,null],[164096,"2026-08-17T16:34:17",52,"/ @sweetkittywitch 👀",114768,null],[164105,"2026-08-17T16:38:05",41,"Пока работаю, после 19 смогу",164096,null],[164395,"2026-08-17T20:44:28",52,"/ @sweetkittywitch 👀",114768,null],[164472,"2026-08-18T08:07:26",52,"/ @sweetkittywitch 👀",114768,null],[165044,"2026-08-18T23:13:54",41,"Сори. Давайте завтра. Как раз день свободный",164472,null],[165874,"2026-08-20T11:23:28",52,"/ @sweetkittywitch 👀",114768,null],[165913,"2026-08-20T11:54:48",41,"( Сегодня точно смогу. Это Пипец какой-то с работой",114768,null],[165914,"2026-08-20T11:55:07",41,"( выжатая как губка",114768,null],[165915,"2026-08-20T11:55:15",41,"( тегните меня вечером пж",114768,null],[166898,"2026-08-20T23:38:49",41,"Нельзя скрыться от леса, когда твои ноги вжимаются в землю оставляя огромные и пахучие следы. \n\nНельзя скрыться от леса, когда твои лапы лепят на себя листья, унося их туда где их быть не должно.\n\nГерои услышали очередной вопль, на этот раз отчетливо, затем увидели что-то в кустах. Это что-то от них не скрывалось достаточно чтоб они увидели голову волка — висящую вверх ногами",114768,null],[166975,"2026-08-21T10:19:09",52,"Гракх замер. Резко, будто напоролся на невидимое лезвие. Рука, уже тянувшаяся к копью, застыла.\n\nОн смотрел на голову волка. Висящую вверх ногами. В кустах.\nЛес выдохнул и затаился. Даже ветер стих, только где-то вдалеке капнула вода с листа.\n\nГракх стоял неподвижно, вглядываясь в сумрак. Пальцы всё ещё сжимали перо Джени. Он чувствовал его влажную прохладу, и это единственное, что удерживало его от того, чтобы рвануть вперёд, круша всё на своём пути. Нет. Нельзя.\n\nОн медленно перевёл взгляд с волчьей головы на землю под ней. Искал следы: капли крови, отпечатки лап, следы волочения. Кто-то повесил это здесь, на уровне глаз. Не зверь. Зверь не вешает трофеи на кусты.\n\n- Вижу, - ответил он на свой же вопрос тихо, почти одними губами.\n\nГракх сделал шаг вперёд. Потом ещё один. Остановился в трёх шагах от куста, вглядываясь: как срезана голова, есть ли под ней лужа, не шевелится ли что-то в листве.\n\nОн принюхался. Среди сырой земли, гнилого мха и железа он искал запах Джени. Или того, кто был с ней рядом. Гракх медленно обошёл куст справа, держась в тени, не касаясь веток, не нарушая тишину. Одна рука всё ещё на копье, вторая сжимает перо.\n\nГракх замер, не оборачиваясь. Прислушался. Сердце билось ровно, он научился не выдавать себя даже дыханием. Пальцы на копье чуть сжались. Если это ловушка, он встретит её лицом к лицу. \n\n/ @sweetkittywitch Осматриваюсь, пытаюсь понять, кто или что издало звук и анализирую следы. Если вижу угрозу, готовлюсь к бою. Если никого, двигаюсь дальше по тропе в низину.",114768,null],[166976,"2026-08-21T10:23:34",41,"@elsio28  .",114768,null],[166979,"2026-08-21T10:25:50",52,"/ @sweetkittywitch А мне ничего не нужно кинуть на чтение следов, восприятие?",114768,null],[166980,"2026-08-21T10:26:00",5,"— Ктво-то в беде! Я должен помочь!\n\nГрунг поскакал прямо на крик. Голова волка его не интересует.",166898,null],[166981,"2026-08-21T10:26:44",41,"( там же голова волка в посте",166979,null],[166982,"2026-08-21T10:28:03",52,"/ Ну может я узнаю что-то больше чем просто голова волка \n\"Он принюхался. Среди сырой земли, гнилого мха и железа он искал запах Джени. Или того, кто был с ней рядом.\"",114768,null],[166983,"2026-08-21T10:28:50",41,"( Он живой",114768,null],[166984,"2026-08-21T10:29:31",41,"( сори, надо было уточнить",114768,null],[166985,"2026-08-21T10:29:55",52,"/эммм ну ок",114768,null],[166986,"2026-08-21T10:31:17",52,"/ тогда просто в помойку мой пост.\nя осторожно иду дальше на звук",114768,null],[166987,"2026-08-21T10:31:47",41,"( Прости(",166986,null],[166988,"2026-08-21T10:34:10",41,"Кусты прикрывающие волка Под его весом ушли назад и вы смогли увидеть его тело. Он был жив и готов наброситься на вас. \n\nНедалеко вы услышали топот таких же волков",114768,null],[166989,"2026-08-21T10:34:16",41,"( инициативу",114768,null],[166990,"2026-08-21T10:35:10",52,"/roll +d20+3",114768,null],[166992,"2026-08-21T10:37:48",5,"/r +2",114768,null],[166994,"2026-08-21T10:38:11",5,"// крик от тела был?",166988,null],[166996,"2026-08-21T10:41:18",41,"( Возможно",114768,null],[166997,"2026-08-21T10:41:40",52,"/я правильно понимаю что я не в скрытности?",114768,null],[166998,"2026-08-21T10:41:42",5,"// тогда давай драться",114768,null],[166999,"2026-08-21T10:41:49",41,"/r 3d20 волки",114768,null],[167001,"2026-08-21T10:42:06",41,"( ты вроде покинул меньше",166997,null],[167002,"2026-08-21T10:42:42",52,"/вот",160842,null],[167003,"2026-08-21T10:43:46",5,"К'Варсио запрыгивает в кусты к телу и смотрит, от кого шёл крик. И живое ли тело.\n\n— Волки! Тут волки! А ктво кричал?",114768,null],[167004,"2026-08-21T10:46:29",52,"/пока жду ответа и поста пойду кофе налью)",114768,null],[167005,"2026-08-21T10:55:59",41,"( сори, отвечу наверное в 12. Иду в центр занятости",114768,null],[167445,"2026-08-21T15:29:23",52,"/ @sweetkittywitch 👀",114768,null],[167653,"2026-08-21T20:51:00",41,"К'Варсио крит 20\nВолк 3 - 20\nГракх 16\nВолк 2  - 13\nВолк 1 - 8",114768,null],[167654,"2026-08-21T20:51:27",41,"( Грунгу за крит доступно 2 хода в первый раунд",114768,null],[167670,"2026-08-21T21:04:25",5,"/ будет описание?",167003,null],[167671,"2026-08-21T21:04:30",5,"/ и как стоят волки",114768,null],[167672,"2026-08-21T21:05:03",41,"( ща",114768,null],[167673,"2026-08-21T21:05:46",41,"Волки стоят почти в идеальном радиусе круга от вас в 30 фт. Их головы неестественно вывернуты, Но Они живы и готовы напасть",114768,null],[167674,"2026-08-21T21:07:24",5,"/ могу подбежать, чтобы доставать всех волков рукопашной?",167673,null],[167675,"2026-08-21T21:08:25",41,"( всех? Они вас окружили",114768,null],[167676,"2026-08-21T21:09:34",5,"/ кайф",167675,null],[167677,"2026-08-21T21:09:59",5,"/ или в смысле они все далеко?",114768,null],[167678,"2026-08-21T21:10:24",5,"/ я хочу сделать по 1 атаке каждому. Могу? Просто я не пон",114768,null],[167681,"2026-08-21T21:12:58",41,"Да",167677,null],[167682,"2026-08-21T21:13:04",41,"Не можешь",167678,null],[167683,"2026-08-21T21:13:17",41,"( каждый в 30 фт",114768,null],[167684,"2026-08-21T21:13:27",41,"( как круг, где вы в центре",114768,null],[167687,"2026-08-21T21:15:26",5,"Грунг прыгает к самому сильному на вид волку, а его тиара сияет\n\n/ Благословение себе от арта",114768,null],[167688,"2026-08-21T21:15:34",5,"И наносит 3 атаки",114768,null],[167689,"2026-08-21T21:17:03",5,"/r d20+5+d4",114768,null],[167693,"2026-08-21T21:17:47",41,"( куб у крита умножается",114768,null],[167694,"2026-08-21T21:17:58",5,"2 попадания, кинь 2 Спаса тела 12",114768,null],[167695,"2026-08-21T21:18:15",5,"/2d6+3+2d4",114768,null],[167696,"2026-08-21T21:18:25",5,"/r 2d6+3+2d4",114768,null],[167698,"2026-08-21T21:18:32",5,"/r d6+3",114768,null],[167700,"2026-08-21T21:18:39",5,"/ 14",114768,null],[167701,"2026-08-21T21:18:40",41,"/r d20+1 d20+1",114768,null],[167703,"2026-08-21T21:18:53",5,"/r 2d4 ядом",114768,null],[167705,"2026-08-21T21:19:13",5,"/ ход",114768,null],[167706,"2026-08-21T21:19:45",41,"Волк еле держится",114768,null],[167707,"2026-08-21T21:20:04",41,"Второй делает рывок к тебе и окружает",114768,null],[167708,"2026-08-21T21:20:13",41,"@Farkanis твой ход",114768,null],[167709,"2026-08-21T21:21:05",5,"/ моё КД 16",114768,null],[167710,"2026-08-21T21:21:14",5,"/ и я иду спать сейчас",114768,null],[167712,"2026-08-21T21:22:33",41,"( Сори",114768,null],[167713,"2026-08-21T21:22:41",41,"( споки",114768,null],[167780,"2026-08-22T08:30:29",52,"Беру в окружение того который сделал рывок и бью копьём двумя руками",114768,null],[167781,"2026-08-22T08:32:20",52,"/roll +d20+6",114768,null],[167783,"2026-08-22T08:33:37",52,"/roll 1d8+3",114768,null],[167785,"2026-08-22T08:33:53",52,"Делаю шквал ударов",114768,null],[167787,"2026-08-22T08:36:03",52,"/roll 1d4+3",114768,null],[167791,"2026-08-22T08:41:16",52,"Отхожу на максимальное расстояние (общая скорость передвижения 55 футов) и не получаю провоцированую  атаку из-за черты подвижный. В сумме нанесено14 урона",114768,null],[167792,"2026-08-22T08:41:48",52,"Я закончил",114768,null],[168461,"2026-08-23T10:33:04",41,"( всем добри утра. Я сегодня в итоге буду до 5 вечера. Но постараюсь выжать себя на максимум",114768,null],[168462,"2026-08-23T10:33:15",41,"Волк ходит",114768,null],[168463,"2026-08-23T10:35:30",41,"Осмелевшая нечисть подбегает к грунгу, потому что Гракх слишком далеко и вонзает в него свои стальные зубы",114768,null],[168464,"2026-08-23T10:35:55",41,"/r +d20+4",114768,null],[168466,"2026-08-23T10:36:05",41,"( мима",114768,null],[168467,"2026-08-23T10:36:12",5,"// да, 16",114768,null],[168468,"2026-08-23T10:36:37",41,"Еле стоящий волк осмелел от выходки предыдущего и тоже попытался укусить",114768,null],[168469,"2026-08-23T10:36:54",41,"/r d20+5 я не правильно кинула сори",114768,null],[168472,"2026-08-23T10:37:04",41,"( и тоже мимо",114768,null],[168473,"2026-08-23T10:37:14",41,"( Лягушенок ходит",114768,null],[168474,"2026-08-23T10:37:43",5,"Каждый раз, когда волки пытались укусить, грунг просто подпрыгивал над ними и зубы клацали внизу",114768,null],[168475,"2026-08-23T10:37:55",5,"/ а 3 волк где?",114768,null],[168476,"2026-08-23T10:38:13",41,"( все около тебя",114768,null],[168477,"2026-08-23T10:38:47",5,"Грунг режет мечом двух самых хилых волком рядом",114768,null],[168478,"2026-08-23T10:38:50",5,"/r +5",114768,null],[168481,"2026-08-23T10:39:24",41,"( 1 попал кд14",114768,null],[168482,"2026-08-23T10:39:34",5,"/r d6+3+d4",114768,null],[168486,"2026-08-23T10:40:19",41,"Ты идеально обрываешь мучения того волка, который еле держался",114768,null],[168487,"2026-08-23T10:40:32",5,"// это лишнее",168485,null],[168488,"2026-08-23T10:40:36",41,"( кажется я нажала",114768,null],[168489,"2026-08-23T10:40:41",41,"( хотя не",114768,null],[168490,"2026-08-23T10:40:46",41,"( пофиг",114768,null],[168491,"2026-08-23T10:41:31",5,"Грунг угрожающе квакает на второго волка",114768,null],[168492,"2026-08-23T10:41:33",5,"// ход",114768,null],[168493,"2026-08-23T10:41:39",41,"Третий волк лицезрея убийство своего собрата с большей яростью вступил в битву, разрывая грунга когтями",114768,null],[168494,"2026-08-23T10:41:56",41,"/r +d20+5",114768,null],[168496,"2026-08-23T10:42:03",41,"( еле еле",114768,null],[168497,"2026-08-23T10:42:18",41,"/r 2d4+3 атака",114768,null],[168499,"2026-08-23T10:42:38",5,"// укус это прямой контакт с кожей, так что кидай спас тела 12",114768,null],[168500,"2026-08-23T10:42:59",5,"// или тут когти",114768,null],[168501,"2026-08-23T10:43:08",41,"( когти",114768,null],[168502,"2026-08-23T10:43:08",5,"// хз условие прямой контакт",114768,null],[168503,"2026-08-23T10:43:19",41,"( хай будет",114768,null],[168504,"2026-08-23T10:43:29",41,"/r d20+3 спас",114768,null],[168506,"2026-08-23T10:43:59",5,"На когти попадает яд вместе с кровью грунга. И очень быстро он ослабляет волка\n\n// отравленный",114768,null],[168510,"2026-08-23T10:51:18",5,"// ждём сеню?",114768,null],[168517,"2026-08-23T10:58:45",41,"( агась",168510,null],[168518,"2026-08-23T10:58:50",41,"@Farkanis",114768,null],[168519,"2026-08-23T10:59:24",41,"Я чуть чуть перемудрила, может в выходной он занят. Отец все же",114768,null],[168520,"2026-08-23T10:59:55",5,"// ну, будем ждать",114768,null],[168530,"2026-08-23T11:12:19",52,"Гракх с подходит делая одного из волков в окружении, но сохраняя при этом дистанцию (расовая способность дистанция атаки на 5 футов больше обычной). Если волки решат атаковать багбира они получат провоцированую атаку  от грунга.\nАтакует копьём двумя руками.",114768,null],[168532,"2026-08-23T11:13:02",41,"( сори не достал(",114768,null],[168533,"2026-08-23T11:13:17",52,"Делаю шквал ударов",114768,null],[168535,"2026-08-23T11:13:32",41,"( смог",114768,null],[168539,"2026-08-23T11:13:55",41,"( хорошо ! Как добиваешь второго ?",114768,null],[168540,"2026-08-23T11:16:12",52,"Багбир опираясь на копье наносит удар ногой по спине волка ломая ее пополам.\n\nИ спомощью оставшегося движения окружает оставшегося волка, также учитывая расовую способность",114768,null],[168541,"2026-08-23T11:17:23",52,"Я все",114768,null],[168544,"2026-08-23T11:50:05",41,"Последний волк ошарашеный происходящим нападает на Гракха",114768,null],[168545,"2026-08-23T11:50:17",41,"/r d20+5",114768,null],[168547,"2026-08-23T11:50:30",41,"( а стоп, помеха",114768,null],[168549,"2026-08-23T11:50:42",41,"( мимо",114768,null],[168550,"2026-08-23T11:50:46",5,"Увидев, что волк открылся для атаки, грунг всаживает меч ему в спину.\n\n// реакция стража",114768,null],[168551,"2026-08-23T11:50:50",5,"/r +5",114768,null],[168553,"2026-08-23T11:50:56",41,"( не",114768,null],[168554,"2026-08-23T11:50:59",41,"( ходи",114768,null],[168556,"2026-08-23T11:51:31",5,"А затем режет его двумя мечами",114768,null],[168559,"2026-08-23T11:51:48",5,"/r 2d6+3+2d4",114768,null],[168561,"2026-08-23T11:51:49",41,"Давай красивое добивание",114768,null],[168562,"2026-08-23T11:53:31",5,"— Ква! Умри, дикий зверь!\n\nК'варсио запрыгивает на спину волка, пригибается к холке и всаживает меч в горло. Волк постепенно оседает под ним.",114768,null],[168646,"2026-08-23T12:33:19",41,"( скоро отвечу",114768,null],[168648,"2026-08-23T12:33:37",41,"(боевая ситуация окончена",114768,null],[168652,"2026-08-23T12:34:13",5,"Лягушонок оглядывается в поисках кричавшего, а затем прыгает осмотреть жертву волков. Тело в кустах",114768,null],[168708,"2026-08-23T12:51:21",41,"( анализ",114768,null],[168710,"2026-08-23T12:52:19",5,"/r -1",114768,null],[168712,"2026-08-23T12:52:30",5,"/r d4",114768,null],[168714,"2026-08-23T12:52:38",5,"/ Итого 15",114768,null],[168804,"2026-08-23T13:21:51",41,"Ты понимаешь, совершенно внезапно для себя... Что этот крик издавало не что-то живое. Это странное чувство неестественного не покидало тебя. \n\nОдного от мыслей тебя отвлекло что-то похожее на \"лицо\" вдалеке",114768,null],[168844,"2026-08-23T13:35:07",41,"@Farkanis социалка",114768,null],[168845,"2026-08-23T13:35:19",5,"— Не понимаю...\n\nЛягушонок ещё раз посмотрел на тело, а затем поднял взгляд и смотрит на \"лицо\". Как далеко оно?\n\n— Там что-то есть!",114768,null],[169116,"2026-08-23T15:34:43",41,"Лицо достаточно далеко, чтоб увидеть его было сложно",114768,null],[169120,"2026-08-23T15:41:01",5,"Лягушонок всё-таки хочет понять, что там с телом жертвы",114768,null],[169799,"2026-08-24T10:14:39",52,"Гракх выдохнул. Тяжело, с хрипом, будто только что разжал пальцы, сжимавшие горло врага. Копьё он не опустил - поставил древком на землю и опёрся на него, позволяя себе на мгновение просто стоять.\nЛес снова дышал. Где-то капнула вода, где-то хрустнула ветка - обычные звуки. Не те, что были раньше.\nОн перевёл взгляд на лягушонка. Тот уже копошился в кустах у тела, а потом замер, уставившись вдаль.\n— Там что-то есть! — донёсся голос К'варсио.\nГракх не спешил. Он подошёл к волку, которого добил, присел на корточки и провёл пальцем по шерсти - мокрой, грязной (осматриваю следы болезни или бешенства). Просто зверь. Кто-то привёл их сюда. Или лес.\nОн выпрямился, поднял голову и посмотрел в ту сторону, куда указывал лягушонок. Лицо. Или что-то похожее на лицо. Далеко. Слишком далеко.\n- Где? - спросил он негромко, подходя ближе к К'варсио.\nГракх встал рядом, прищурился, вглядываясь в сумрак между стволов. Одна рука на копье, вторая слегка касается серьги.\n- Ты уверен? - спросил он тихо. - Или тебе показалось после боя?\nОн ждал ответа, но сам уже знал - в этом лесу ничего не бывает просто так. И если лягушонок что-то увидел, значит, это кто-то хотел, чтобы его увидели.\n\n/ Стою рядом с К'варсио, смотрю в указанном направлении. Если там действительно что-то есть, пытаюсь разглядеть. Не двигаюсь в ту сторону, пока не пойму, что именно мы видим.",114768,null],[169805,"2026-08-24T10:36:05",52,"/ @sweetkittywitch @elsio28",114768,null],[169810,"2026-08-24T10:52:14",41,"( бегу, Только с собеседования",114768,null],[169826,"2026-08-24T12:14:55",41,"В 13 начнем. Работу доделаю",114768,null],[169832,"2026-08-24T13:09:40",5,"— Лицо! Это лицо!",169799,null],[169834,"2026-08-24T13:25:46",41,"/Внимательность",169799,null],[169842,"2026-08-24T13:30:23",52,"/roll 1d20+5",114768,null],[169848,"2026-08-24T13:34:15",41,"( теперь общую проверку мудрости",114768,null],[169849,"2026-08-24T13:34:52",41,"( и я опишу, что именно ты увидел",114768,null],[169850,"2026-08-24T13:35:10",52,"/roll 1d20+3",114768,null],[169863,"2026-08-24T13:53:37",41,"В висках начало покалывать, когда ты примотрелся к лицу-маске. На него падали тени от листьев и легкий туман оседал. \n\nМистическая фигура, явно не человеческая, развернулась и принялась бежать прочь от вас, с неестественным шелестом. Будто по земле стучали множество ног",114768,null],[169868,"2026-08-24T13:57:35",52,"Использую рывок (110 футов ), если этого не хватает поступь ветра (220 футов)",114768,null],[169873,"2026-08-24T13:58:37",41,"( ДОГНАЛ!",114768,null],[169874,"2026-08-24T13:58:53",41,"( Опиши и я отпишу красивую поимку существа",114768,null],[169884,"2026-08-24T14:04:30",52,"Когда фигура сорвалась с места, я не бросился в погоню - я позволил теням поглотить меня. В мгновение ока я сливаюсь с пляшущими на земле силуэтами от листьев. Мой рывок превращается в серию неестественно длинных, рваных прыжков сквозь полумрак, а когда дистанция кажется недосягаемой, сама реальность под моими ногами словно истончается. С помощью Поступи ветра я превращаюсь в размытую полосу черного тумана, проносясь сквозь туман быстрее, чем он успевает осесть, сокращая расстояние до цели прежде, чем она успеет осознать моё присутствие.",114768,null],[169901,"2026-08-24T14:21:03",41,"Так и произошло. Сама природа сочла тебя частью себя, позволив поймать своё детя. \n\nОказавшись в считаных сантиметрах от существа ты понял, этот дух... Похож на ту женщину, которой ставили чучело в деревне и сжигали. \n\nМаска, рога, пляшущий туман. Её называют...Наму. Хранительница дорог. \n\nВ Её руках-корнях находилась кучка света, меха и маленьких хвостов . Даже пойманной Она не расцепляла хватку. \n\n— Отпусти... \n\nЭхом послышался голос величественного существа, сжатого в твоих руках",114768,null],[169905,"2026-08-24T14:22:04",5,"К'варсио тем временем прыгает по лесу в сторону внезапного рывка багбира",114768,null],[169907,"2026-08-24T14:23:00",52,"/ Круто)) \n Я сейчас не у пк не хочу ломать атмосферу сухими постами ) попозже отпишу )",114768,null],[169908,"2026-08-24T14:23:11",41,"( оке, ждем",114768,null],[169988,"2026-08-24T17:50:32",52,"Гракх не разжал хватку. Пальцы впились в плечи существа - не грубо, но так, чтобы она не могла вырваться. Он чувствовал, как под его ладонями пульсирует что-то живое, но не плотское. Тёплое. Как утренний туман, если сжать его в кулак.\nОн смотрел на неё. На маску. На рога. На руки-корни, которые сжимали свет, мех и маленькие хвосты. Она была точь-в-точь та женщина с чучела. Та, которую сжигали на ритуале.\n-Ты, - сказал он тихо. Не вопрос. Утверждение.\nОн не отпускал. Но и не сжимал сильнее.\n- Не убегай, - голос его был низким, без угрозы. - Я не причиню тебе вреда.\nГракх перевёл взгляд на её руки. На то, что она держала.\n- Ты их спасла? - спросил он. - Или поймала?\nОн стоял неподвижно, давая ей время ответить. Сердце билось ровно. Вокруг лес замер - ни ветки, ни звука. Даже туман перестал плясать. Только они двое. И маленькие хвосты в её ладонях.\n- Я не из тех, кто жёг твоё чучело, - сказал он. - Я ищу другую. Она называется Джени. Может, ты знаешь её?\nГракх ждал. Ждал, что она скажет. Или сделает. Или исчезнет. Но он был готов ко всему.",114768,null],[169989,"2026-08-24T17:51:01",41,"( Как не убегать, когда вы так умело ловите?(",114768,null],[169990,"2026-08-24T17:51:19",41,"( ща доделаю работу и отпишу , там чуть чуть осталось",114768,null],[169991,"2026-08-24T17:51:36",52,"/ у меня закончилось если что ци)))",114768,null],[169992,"2026-08-24T17:51:58",52,"/ 2 шквала и поступь ветра)) я все)",114768,null],[170101,"2026-08-24T18:55:32",41,"( закончила, ща отпишу",114768,null],[170526,"2026-08-24T19:56:33",41,"Дух перестала шевелиться, замерла. Смиренно отвечала На вопросы. \n\n— Духи этого леса, мои дети. Имя мне Наму, ты должен это знать...\n\n\nМягкий голос раздавался эхом, как ветер меж деревьями \n\n— Я знаю о твоей подруге, но не могу её достать. В сердце леса тебе нужно её искать...\n\nГолова духа слегка наклонилась вперед\n\n— Но она заперта там, мной. Потому что там не лишь она... Чужеземцы Пришли сюда и использовали её ради своей холодной и грязной науки...  Сердце леса, наш якорь, у них в руках... Потому я заперла их в нем. \n\nПосле этих слов, она болезненно обняла в руках, прижатая к земле\n\n— Но скоро они вырвутся, ведь я потеряю равновесие",114768,null],[170547,"2026-08-24T19:58:44",41,"@Farkanis  .",114768,null],[170548,"2026-08-24T19:58:57",41,"Её слова слышит и жаб",114768,null],[170640,"2026-08-24T20:09:17",5,"— Кто это? Зачем ты её схватил, Гракх?\n\nГрунг припрыгал поближе и смотрит на девушку-духа.\n\n— Квакие чужеземцы, Наму? Они злые? Или духи леса злые? В деревне кварят по-разному",114768,null],[170671,"2026-08-24T20:12:08",41,"— Они называют себя \"Ученые\"",114768,null],[170673,"2026-08-24T20:12:19",41,"( те, кого вы должны спасти. Точнее К'Варисио. Он пришел по заданию  )",114768,null],[170693,"2026-08-24T20:14:18",5,"// да? У меня поручение архифеи разобраться кто тут хороший",170673,null],[170695,"2026-08-24T20:14:23",5,"// а какое задание?",114768,null],[170696,"2026-08-24T20:14:29",41,"( а, тогда пох",170693,null],[170697,"2026-08-24T20:14:46",41,"( я думала ты читал квестовую листовку",170695,null],[170702,"2026-08-24T20:15:17",41,"( справедливости ради, все спасатели слились",114768,null],[170707,"2026-08-24T20:15:46",5,"— А что они делают? И вы духи, добрые или нет?",170671,null],[170715,"2026-08-24T20:16:48",41,"— У духов нет грани добра и зла, лишь я не могу причинить вред смертным. Только запереть их за большее зло... Я дух дорог, а не сердца леса",114768,null],[170773,"2026-08-24T20:25:38",5,"— Так что же эти учёные. Чтво они сделали? Зачем держать их?",114768,null],[170790,"2026-08-24T20:27:53",41,"— Они забрали сердце леса...наше единственное сокровище",114768,null],[170799,"2026-08-24T20:29:59",5,"— Я не понимаю.\n\nГрунг моргнул.\n\n— Ты же заперла их в лесу. И сердце с ними?",170790,null],[171662,"2026-08-24T22:30:26",41,"— Да, но они отказываются вернуть его назад\n\nСказала дух",170799,null],[172105,"2026-08-25T06:49:52",5,"К'варсио немного подумал.\n\n— Я знаю квак сделать справедливо. Учёные должны вернуть сердце, а духи — отпустить ученых!",114768,null],[172106,"2026-08-25T09:45:02",52,"Гракх слушал. Стоял неподвижно, и его пальцы всё ещё сжимали плечи Наму - не сдавливая, но и не отпуская. Он смотрел на неё, на её руки-корни, на свет, мех и маленькие хвосты, которые она прижимала к себе.\n\n- Ты заперла их в сердце леса, - повторил он медленно, обдумывая каждое слово. - Вместе с сердцем. И теперь они не отдают его.\n\nОн перевёл взгляд на К'варсио. Тот говорил о справедливости, о том, что учёные должны вернуть сердце, а духи - отпустить их. Просто. Ясно. По-лягушачьи.\nГракх посмотрел на Наму. В её маске, в её глазах, которые он не видел, но чувствовал, он искал ответ на другой вопрос.\n\n- Ты сказала, что не можешь причинить вред смертным, - произнёс он. - Только запереть их. А если они вырвутся?\n\nПауза. Лес молчал.\n\n- Что тогда случится с лесом? - спросил он. - С тобой? С духами?\n\nОн ждал ответа. Но внутри себя он уже знал, что должен делать. И это было не про справедливость. Не про учёных. Не про духов.\nЭто было про силу.\nОн хотел стать сильнее. Он пришёл в этот лес не за духами и не за учёными. Он пришёл за силой и Джейн. За той силой, что позволит ему вернуться в клан победителем. За той, что сделает его имя - Тенеклык - произносимым с уважением и страхом.\nНаму говорила о сердце леса. О якоре. О чём-то, что держит этот лес и всех его духов. Если это сердце даёт силу... если оно может сделать его сильнее...\n\n- Я помогу тебе, - сказал он тихо. - Я пойду в сердце леса. Я заберу сердце у них. И верну его лесу.\n\nОн посмотрел на неё в упор. Прямо. Без страха.\n\n- Но взамен я хочу кое-что. Я хочу стать сильнее. Я хочу силу, которая позволит мне вернуться к своему народу. Чтобы они не смели смотреть на меня как на изгнанника, а также ты отпустишь Джени.\n\nГракх замолчал. Его пальцы чуть разжались на плечах Наму.\n\n- Это справедливо? - спросил он. - Ты возвращаешь сердце леса. Я получаю силу и Джени.\n\nЛес замер. Даже ветер стих. Только Наму стояла перед ним с маленькими хвостами в руках.\n\n@sweetkittywitch @elsio28",114768,null],[173238,"2026-08-26T14:11:08",52,"/ @sweetkittywitch 👀",114768,null],[173239,"2026-08-26T14:12:01",41,"( отпишу, но чуть ближе к вечеру. Работаю",173238,null],[173805,"2026-08-26T19:58:05",52,"/ @sweetkittywitch 👀",114768,null],[173807,"2026-08-26T19:58:21",41,"( помню",114768,null],[173808,"2026-08-26T19:58:27",41,"( сори, в пути",114768,null],[174677,"2026-08-27T13:55:16",41,"— Я согласна на твою просьбу\n\nВетер дул, проходя сквозняком сквозь воина и духа. Грунг стоял рядом, все обдумывая. Наму делала тоже самое. \n\n— Вернув сердце...ты докажешь, что не просто достоин этой силы, а что уже силен... Однако я согласна сделать тебе такой подарок...взамен на вашу помощь. Чего же хочет твой друг? \n\nОна склонила голову в бок на К'Варсио. Ветер продавал шерстку маленьких духов. В этом ветру грунг услышал знакомый смех — смех своей феи",114768,null],[174738,"2026-08-27T14:23:43",41,"@elsio28 @Farkanis",114768,null],[174843,"2026-08-27T15:26:22",5,"— Я хочу, чтобы никто добрый не пострадал! Учёные уйдут невредимыми, когда вернут сердце. Скважи духам не вредить им.",174677,null],[174849,"2026-08-27T15:31:20",41,"— Тому и быть... Следуйте за мной... \n\nЗемля поглотила Наму прямо из под рук Гракха, заставив того опешить от факта того, что она могла сбежать все это время. \n\nФигура женщины вышла из за ближайшего дерева и продолжила свой путь вглубь леса. Однако время от времени останавливалась, ожидая вас.",174843,null],[174851,"2026-08-27T15:32:07",5,"К'варсио поскакал за ней по лесу.\n\n— А почему духи перестали помогать деревне?",114768,null],[174852,"2026-08-27T15:32:47",41,"— без сердца, у духов нет цели. Они не злые, лишь сломанные отчаянием...",114768,null],[174854,"2026-08-27T15:33:32",5,"— Значит я кверну сердца, кверну цель!",114768,null],[174858,"2026-08-27T15:34:56",41,"— Ты добрый лягушенок... \n\nВы продолжаете путь, грунг чувствует как земля под ногами немного движется \n\n( бросок магии или истории",114768,null],[174859,"2026-08-27T15:35:14",5,"/r +1 магия",114768,null],[174862,"2026-08-27T15:36:30",41,"Это фейские тропы, но слабее. Должно быть к сердцу трудно попасть просто через лес. Интересно, как туда попали ученые? \n\n...Им помогла та самая Джени?",114768,null],[174868,"2026-08-27T15:38:30",5,"— Это тропы фей... Наму, а как учёные пробрались в ваш лес?",114768,null],[174869,"2026-08-27T15:39:59",52,"Гракх остановился, когда поравнялся с К'варсио. Сделал шаг вперёд, потом второй - медленно, давая лягушонку время понять, что он не уходит, а просто встаёт рядом. Поравнялся с ним, глядя в ту сторону тропы.\n\n- Ты сказал, что учёные должны уйти невредимыми, - произнёс он негромко, не оборачиваясь. Голос был ровным, без угрозы. Просто вопрос. - А если они не захотят отдавать сердце? Если они будут драться?\n\nГракх повернул голову, взглянув на лягушонка сверху вниз. Тени от листьев плясали на его лице.\n\n- Ты готов к этому? К тому, что они могут выбрать не возвращать?\n\nОн выдержал паузу, давая вопросу осесть в сыром воздухе.\n\n- Я готов, - сказал он тихо. И в этом не было вызова. Просто факт. - Но мне важно знать, с кем я иду.\n\nГракх развернулся и двинулся дальше по тропе, туда, где между деревьями уже виднелся просвет. Джени ждала.\n\nОн не обернулся. Только добавил через плечо, уже почти на ходу:\n- Догоняй. Я буду ждать у входа.\n\nИ шагнул вперёд, оставляя К'варсио позади с его вопросами и его верой в то, что добро всегда может договориться.",114768,null],[174870,"2026-08-27T15:43:00",5,"— Они должны отдать сердце, оно принадлежит лесу. Я — рыцарь, заставлю, если не захотят. Но постараюсь никого не убивать. И ты старайся, Гракх!",174869,null],[174871,"2026-08-27T15:45:43",52,"/ я ушел  по тропе держась скрытно, на сколько возможно",114768,null],[174872,"2026-08-27T15:46:08",41,"— Чужие истории им помогли. Это работает, раз у них нет своих...",174868,null],[174873,"2026-08-27T15:46:30",52,"/ и если есть возможность защитить это за короткий отдых будет супер",114768,null],[174874,"2026-08-27T15:46:40",41,"( есть",114768,null],[174875,"2026-08-27T15:50:29",52,"/ @elsio28 догоняй)) я думаю она сказала все что может)",114768,null],[174876,"2026-08-27T15:58:52",5,"Грунг задумался и попрыгал по тропе дальше",174872,null],[174878,"2026-08-27T16:05:52",41,"Вы приходите к огромному древу, невообразимо уходящему вверх, далеко в небеса. Вы не видели его конца, не знали: А есть ли этот конец? \n\nИз дерева прорезалось темное дупло, от которого веяло влагой и теплом. \n\nНаму остановилась перед ним. \n\n— Дальше я пройти не смогу, буду ждать вас здесь. Я узнаю, когда вы захотите выбраться...",114768,null],[174879,"2026-08-27T16:07:52",5,"— А духи там внутри тоже?",114768,null],[174880,"2026-08-27T16:08:41",41,"— да... Их поймали...",114768,null],[174881,"2026-08-27T16:09:38",5,"— Значит я выпущу всех. Ква! Что там дальше в дупле?",114768,null],[174882,"2026-08-27T16:12:12",52,"Гракх остановился перед деревом. Стоял, задрав голову, и смотрел вверх — туда, где ствол уходил в небо и терялся где-то за облаками. Дерево было старым. Старше его клана. Старше леса вокруг. Старше всего, что он знал.\nОн перевёл взгляд на дупло. Тёмное. Влажное. Тёплое — оттуда тянуло чем-то живым, глубоким, как дыхание спящего зверя.\n\n- Я узнаю, когда вы захотите выбраться, - сказала Наму.\n\nГракх кивнул. Не обернулся. Просто стоял, сжимая копьё, и смотрел в темноту.\n\n- Ты слышал, что она сказала, - произнёс он негромко, скорее для К'варсио, чем для себя. - Дальше только мы.\n\nОн сделал шаг к дуплу. Остановился. Повернул голову, взглянув на лягушонка.\n\n- Я попытаюсь не убивать, - сказал он. И в голосе его не было обещания. Было что-то другое. Понимание. - Но я не дам им забрать то, что я искал.\n\nГракх развернулся и шагнул в темноту дупла. Копьё наготове. Сердце бьётся ровно. \n\n/ Шагаю в дупло первым в скрытности. Оружие наготове. Осматриваюсь, пытаюсь понять, что внутри: освещение, размеры помещения, наличие существ, запахи, звуки. Если вижу угрозу - готовлюсь к бою. Если никого - жду, пока К'варсио зайдёт, и двигаюсь дальше вглубь.",114768,null],[174883,"2026-08-27T16:12:27",41,"—... Сердце...",174881,null],[174884,"2026-08-27T16:13:06",52,"/ Слежу за реакцией своей серьги",114768,null],[174885,"2026-08-27T16:13:59",5,"— Иду!\n\nГрунг запрыгнул следом",114768,null],[174886,"2026-08-27T16:17:25",41,"Дупло внутри ощущается как тоннель, вдали виден свет",114768,null],[174887,"2026-08-27T16:18:33",52,"Иду дальше на свет, осторожно \n\n/ как будто мало информации)",114768,null],[174888,"2026-08-27T16:21:05",41,"( Загрузка мира",114768,null],[174897,"2026-08-27T16:38:24",41,"Проходя к свету вы выходите в чуть ли не висячие сады Вавилона:\n\nБелый камень - выточеный самой природой, заросшие статуи - омытые вековыми водопадами, но нигде не видно духов. \n\nЗа то за светом вы видите сгорбившейся фигуру с мачете или подобным инстпументом. Фигура низкая, почти детская. \n\nКак только глаза привыкают к свету. Вы видите, что самое небо не просто пустота, а мозайка, что парит в воздухе",114768,null],[174899,"2026-08-27T16:47:07",52,"Гракх шагнул в тоннель. Свет впереди становился ярче, но не резким, не режущим - тёплым, как от старого очага. Стены дупла были влажными на ощупь, и где-то вдалеке капала вода.\nОн шёл медленно, держа копьё наготове, прислушиваясь к своей серьга на ухе. Он доверял ей. Она ещё ни разу не подводила.\n\nКогда свет стал почти невыносимым, Гракх вышел из тоннеля.\nОн увидел белый камень, водопады, статуи, заросшие мхом. Увидел, как это всё парит в воздухе. Увидел небо, которое было мозаикой, - тысячи кусочков света, сложенных в узор. Небо, которое не было пустотой.\n\nГракх перевёл взгляд вперёд. Там, у края света, стояла фигура. Низкая, почти детская. Сгорбленная. В руках - что-то похожее на мачете или тяпку. Она не двигалась. Просто стояла, будто ждала.\n\nГракх прищурился, вглядываясь. Потом повернул голову к К'варсио.\n\n- Ты видишь её? - спросил он негромко.\n\nОн не двигался вперёд. Ждал. Наблюдал.\n\n/ Стою на месте, рассматриваю фигуру и пространство вокруг. Ищу следы других существ, звуки, движение. Фигуру не трогаю, пока не пойму, кто это и живая ли она. Прислушиваюсь к серьге.",114768,null],[174900,"2026-08-27T16:49:08",41,"( внимание. Серьга не реагирует",114768,null],[174902,"2026-08-27T16:51:55",52,"/roll 1d20+5",114768,null],[174905,"2026-08-27T16:54:35",41,"Вода журчит, где-то вдали что-то \"шуршит\" как фон. Фигура бормочет. Она идет ближе к вам, вы скрываетесь?",114768,null],[174906,"2026-08-27T16:55:10",52,"/я изночально двигался скрытно",114768,null],[174909,"2026-08-27T16:59:39",52,"Гракх стоял неподвижно, вглядываясь в фигуру. Серьга молчала - не грелась, не вибрировала. Никакой угрозы. Или та, что скрывалась лучше, чем он мог почувствовать.\n\nОн услышал журчание воды, ровное, успокаивающее. И где-то на фоне - шуршание. Постоянное, будто ветер перебирал листву. Или будто кто-то шевелился там, за пределами видимости.\nФигура бормотала. Низкая, сгорбленная, с мачете в руках — она двигалась в их сторону. Медленно, но целенаправленно.\nГракх сжал копьё, но не поднял. Не обнажил оружие.\nОн сделал шаг назад, в тень, которую отбрасывал край тоннеля. Бесшумно. Плавно. Сливаясь с камнем и мхом, как учил его старый монах много лет назад.\n\n- Тише, - сказал он одними губами, не оборачиваясь к К'варсио. - Не двигайся.\nОн замер в тени, держа копьё параллельно земле, готовый к любому развитию. Наблюдал за приближающейся фигурой, стараясь разобрать, что она бормочет, как двигается, куда смотрит.\n\n/ Скрываюсь в тени у входа в тоннель. Наблюдаю за фигурой. Пытаюсь разобрать её бормотание. Если она не заметит нас и пройдёт мимо - не вмешиваюсь. Если заметит и проявит агрессию - готовлюсь к бою.",114768,null],[174910,"2026-08-27T17:01:51",41,"( Кинь скрытность",114768,null],[174911,"2026-08-27T17:02:10",41,"( и ждем @elsio28  .",114768,null],[174912,"2026-08-27T17:02:16",52,"/roll 1d20+5",114768,null],[174914,"2026-08-27T17:02:36",5,"/ пока занят(",114768,null],[174957,"2026-08-27T17:50:05",5,"— Вижу. Я не буду прятаться, я пришёл сюда решить дела миром.\n\nГрунг вышел в центр коридора и встал напротив фигуры. Руки подняты, оружия нет.\n\n— Привет! Мы пришли вернуть духам сердце. Ты один из них, не так ли?",174899,null],[174959,"2026-08-27T17:51:42",41,"Фигурой оказался гоблин, просто очень лохматый \n\n— А-а-а-а! Я НЕ ДУХ! А ТЫ КТО ВООБЩЕ ТАКОЙ!? \n\nОн дрожащими руками тыкает мачете в твою сторону",114768,null],[174960,"2026-08-27T17:52:34",5,"— Квоблин? Что ты здесь делаешь? Я тебе не наврежу!",114768,null],[174963,"2026-08-27T17:53:28",41,"— Я тут просто работаю! Г-грубая сила...г-г-грязная...!",114768,null],[174964,"2026-08-27T17:53:40",41,"Отвечает гоблин",114768,null],[174967,"2026-08-27T17:54:16",52,"Со всей дури бью из скрытности ему в морду так, чтоб он остался жив но выронил мачете, которое наставил на моего товарища",114768,null],[174968,"2026-08-27T17:54:40",41,"( атака",114768,null],[174970,"2026-08-27T17:54:45",5,"— Работаешь? У кого? Ты видел духов?",114768,null],[174972,"2026-08-27T17:55:03",52,"/roll +d20+6",114768,null],[174975,"2026-08-27T17:55:15",41,"Твою Речь прорывает будто с неба свалившийся тумак по гоблину",114768,null],[174977,"2026-08-27T17:55:55",5,"Грунг квакнул от неожиданности.\n\n— Зачем ты напал на квоблина!?",114768,null],[174978,"2026-08-27T17:55:57",41,"Бедняга падает на землю, роняя свой мачете. Держится за нос и вопит\n\n— СПАСИТЕ, СПАСИИИТЕ",114768,null],[174980,"2026-08-27T17:56:36",52,"/ сек дайте написать пост)",114768,null],[174989,"2026-08-27T18:02:19",52,"Гракх вышел из тени, опуская копьё. Не убирая, но и не угрожая. Гоблин лежал на земле, держась за нос, и верещал так громко, что, казалось, вот-вот обрушит этот парящий сад на их головы.\nГракх наступил ногой на мачете, отодвигая его подальше от дрожащей руки гоблина, и присел на корточки рядом с ним. Не спеша. Без резких движений.\n\n- Зачем ты напал на квоблина!? - донёсся голос К'варсио.\n\nГракх не обернулся. Только покачал головой, глядя на гоблина, который корчился на земле.\n\n- Он наставил мачете на тебя, - сказал он ровно, без раздражения. - Ты стоял с поднятыми руками, без оружия, и он всё равно направил на тебя лезвие. Я не ждал, пока он решит им воспользоваться.\n\nГракх перевёл взгляд на гоблина и заговорил на его языке - грубо, отрывисто, как и положено тому, кто знает их племена.\n\n- Хватит орать, - сказал он на гоблинском. Голос низкий, спокойный. - Я тебя не убью. Если ты перестанешь вопить и ответишь на вопросы.\n\nОн выдержал паузу, давая гоблину время переварить слова на его родном языке. Багбиры и гоблины говорили на одном наречии - грубом, режущем слух, но понятном каждому, кто вырос в диких землях. Гракх знал, как говорить с ними. Только сила и прямота.\n\n- Ты работаешь здесь, - продолжил он. - На кого? На духов? На учёных? Говори, и я не трону тебя больше.\n\nОн не поднимал голоса. Просто ждал, глядя гоблину в глаза, сжимая копьё так, чтобы тот видел: он умеет бить, если понадобится.\n\n/ Говорю на гоблинском. Стою на коленях рядом с гоблином, сохраняю зрительный контакт. Мачете под моей ногой. Если гоблин ответит - слушаю. Если попытается сбежать или атаковать - готов к действию.",114768,null],[175003,"2026-08-27T18:07:12",5,"— Очень грубо. Не всё можно решить силой, ква!\n\nРасстроенный грунг присел в сторонке и смотрит на мозаику в небе.",114768,null],[175199,"2026-08-27T19:17:01",41,"Гоблин начал крехтеть на своем языке так, как всегда говорил \n\n— а...а Какой ответ вас устроит? \n\nХнык",114768,null],[175285,"2026-08-27T19:43:36",52,"Гракх схватил двумя пальцами за разбитый нос гоблина и начал его слегка выкручивать. \n\n- Только правдивые ответы. - сказал он на его языке.",114768,null],[175286,"2026-08-27T19:45:27",41,"Гоблин попытался закричать, но захлопнул собственный рот чтоб Гракх не делал ему ещё больнее. \n\nНа крики ещё никто не пришел, шум вдали продолжается",114768,null],[175288,"2026-08-27T19:46:13",5,"— Прекрати! Ты не умеешь общаться цивилизованно?",175285,null],[175302,"2026-08-27T19:51:12",52,"Хочу понять что за шум. Прислушиваюсь и оцениваю обстановку.\n\n- Если на нас нападут ты умрёшь первый - сказал он гоблину на его языке.\n\n— Прекрати! Ты не умеешь общаться цивилизованно?- вмешался лягушенок.\n\nГракх бросил на его раздражений взгляд и отпустил нос гоблина.\n\n- Ладно, сам с ним говори.- большая фигура поднялась и ногой пнула в сторону мачете. Гракх отошёл в сторону, оценивая обстановку.\n\n/ Оцениваю обстановку и по возможности ухожу в скрытность.",114768,null],[175304,"2026-08-27T19:52:03",41,"( ты идешь ближе к шуму в скрытности и слушаешь? Кидай",114768,null],[175306,"2026-08-27T19:52:26",52,"/да",175304,null],[175309,"2026-08-27T19:52:54",41,"Это скрытность",114768,null],[175312,"2026-08-27T19:53:05",52,"Да",114768,null],[175315,"2026-08-27T19:53:54",41,"( и внимание",114768,null],[175318,"2026-08-27T19:54:13",41,"( хорошо, ща",114768,null],[175319,"2026-08-27T19:54:19",41,"@elsio28  .",114768,null],[175322,"2026-08-27T19:55:14",5,"К'варсио подошёл к гоблину и помог подняться.\n\n— Тш, извини за этого грубияна. Ты в порядке? Хочешь, выведу тебя отсюда?",114768,null],[175333,"2026-08-27T19:57:31",41,"— д-да...шмыг \n\n...я по дочке скучаю( Мы уже три дня пытаемся выйти, а там закрыто(((",114768,null],[175347,"2026-08-27T20:00:11",5,"— Мы только что зашли. Идём, я выведу тебя!\n\nК'варсио направляется по коридору к выходу и ведёт гоблина",114768,null],[175348,"2026-08-27T20:00:28",41,"А там закрыто",114768,null],[175350,"2026-08-27T20:01:28",5,"Стучит лапкой.\n\n— Наму, отпирай!",114768,null],[175352,"2026-08-27T20:02:23",52,"/ Я каждый свой ход ищу следы и анализирую звуки, запахи и реакцию серьги",114768,null],[175358,"2026-08-27T20:02:58",41,"Но Наму не отпирает",175350,null],[175362,"2026-08-27T20:03:46",41,"Ты слышишь и видишь переговоры, раскопки и расчищение камней гоблинами. Все Они очень активно заняты работой и даже не слышат тебя пока что",175352,null],[175369,"2026-08-27T20:04:45",5,"— Ква!\n\nВиновато смотрит на гоблина.\n\n— Она не откроет, пока мы не найдём сердце леса. Извини! Посиди тут, отдохни, мы скоро вернёмся",114768,null],[175390,"2026-08-27T20:07:20",41,"— подожди...вы Авантюристы??? Сыщики или просто...м...м?",114768,null],[175394,"2026-08-27T20:07:43",41,"Он не мог сказать",114768,null],[175397,"2026-08-27T20:08:32",52,"Гракх слушал переговоры краем уха, но сам уже двигался. Пока К'варсио возился с гоблином и стучал в закрывшийся проход, багбир бесшумно скользнул в тень.\nОн не спешил. Он всматривался, вслушивался, внюхивался. Каждый шаг ставил так, чтобы не хрустнул камень под ногой. Каждое движение - плавное, текучее, как учил старый монах.\nВдалеке он видел гоблинов. Много. Они копошились у камней, расчищали что-то, таскали, стучали. Никто из них не смотрел в его сторону.\nГракх нашёл удобную позицию - за статуей, поросшей мхом, откуда открывался обзор на всю поляну. Он присел, сливаясь с камнем, и начал наблюдать.\nОн искал главного. Того, кто отдаёт приказы. Того, кто стоит чуть в стороне и не работает руками, а только смотрит и указывает. Того, кто носит что-то другое - не такую грязную одежду, как у остальных, или оружие получше, или ведёт себя иначе.\nГракх ждал. Дышал ровно. Серьга молчала. Лес внутри этого места жил своей жизнью, но пока - не против него.\n\n/ В скрытности. Наблюдаю за гоблинами, ищу главного. Не вмешиваюсь, пока не пойму структуру и не увижу, кто ими руководит. Если замечу лидера - запоминаю его местоположение и манеру поведения, прежде чем действовать.",114768,null],[175406,"2026-08-27T20:10:49",5,"— Авантюриствы? Нет, я пришёл по велению моей кваспожи архифеи. Восстановить справедливость. Вернуть сердце духам, а ученых — домой",175390,null],[175413,"2026-08-27T20:12:07",41,"— Ясно, значит сердце… то есть якорь все же нужно вернуть ? Мы же… шмыг… так старались ради него((",175406,null],[175435,"2026-08-27T20:15:44",5,"— Вы... учёные? Квачем вам сердце? Духи без него пустые, не могут помогать дервеням!",175413,null],[175454,"2026-08-27T20:19:09",41,"— Мы… ну… госпожа нас просит, мы просто р-работаем. Мы не ученые, мы рабы… \n\nШмыг\n\n— Я драться не умею на самом деле, этот нож просто для травы…",175435,null],[175455,"2026-08-27T20:19:26",41,"( ща отпишу Сене большой пост",114768,null],[175460,"2026-08-27T20:20:21",5,"— Рабы?\n\nГрунг удивлённо смотрит на гоблина.\n\n— Где эта ква-гаспожа? Я заставлю её отпустить вас всех!",175454,null],[175462,"2026-08-27T20:21:09",41,"— Ой … она будет злиться",114768,null],[175464,"2026-08-27T20:22:08",52,"/ убить гоблинцев) они Джени похитили) а значит злые)",114768,null],[175465,"2026-08-27T20:23:50",5,"— Ты хочешь стать свободным? Идти, ква-куда сердце прикажет. Делать, что хочется.",175462,null],[175468,"2026-08-27T20:25:24",41,"— н-но я не могу. Дочка тоже в рабстве",175465,null],[175470,"2026-08-27T20:26:19",5,"— Ква-госпожа держит твою дочку? Квоблин, укажи мне направление, я освобожу её!",175468,null],[175472,"2026-08-27T20:27:08",41,"— она далекооо на востоке. Увы не здесь… это меня и держит по хуже всякого сердца леса(",114768,null],[175505,"2026-08-27T20:35:48",41,"Тем временем Кракх видел из какой-то большой палатки вышла девушка азиатской внешности , человек. Она смотрела как работают гоблины и давала указания по расчистке реликвий. \n\nОна дала им указание. \n\n— будьте внимательны к небу, я не могу терять по два гоблина каждый день. Что у вас тут? \n\nПоднеся увеличительное стекло к раскопке. Она тихо читала надписи в слух. Гоблины выглядели так будто не особо понимали их значение\n\n— Поверить не могу, что этот сад все это время был здесь… \n\nОдин из гоблинов, что держал совочек внезапно расплакался и закрыл лицо руками\n\n— мы обречены, агаси Фуюми! \n\n— Не расклеивайтесь, я почти расшифровала якорь. Скоро сама вас выпущу , энергии должно хватить",175397,null],[175515,"2026-08-27T20:36:57",5,"— А ква-госпожа здесь? Я выпущу сначала ква-квас, потом пойду за дочкой, обещаю!",175472,null],[175522,"2026-08-27T20:38:25",41,"— спасибо, добрый жаб( как ваше имя ?",175515,null],[175525,"2026-08-27T20:39:19",5,"— Меня зовут К'варсио",114768,null],[175527,"2026-08-27T20:40:06",41,"— А я… а я Харбит! \n\nОн протянет руку для рукопожатия",114768,null],[175532,"2026-08-27T20:41:03",5,"Грунг достал бинт из рюкзака, обмотал свою лапку, а потом пожал руку гоблина.\n\n— Приятно квазнокомиться! Моя кожа ядовита, вот поэтому...",114768,null],[175536,"2026-08-27T20:43:06",41,"#Харбит\n\n— А , хорошо, спасибо что предупредил :3",114768,null],[175549,"2026-08-27T20:45:13",52,"Гракх замер за статуей, наблюдая. Его взгляд скользнул по гоблинам, по раскопкам, по каменным плитам, которые они расчищали. И остановился на ней. Девушка азиатской внешности, человек. Вышла из палатки, смотрела на работу, давала указания. Говорила спокойно, ровно - и гоблины слушались.\nОн слышал её голос. Слышал, как она говорила о якоре, о расшифровке, об энергии. И о том, что скоро выпустит гоблинов.\nГракх медленно перевёл взгляд на гоблина, который расплакался. На его слова - \"мы обречены\". На то, как он закрыл лицо руками.\nОн перевёл взгляд на К'варсио, который стоял внизу с гоблином и говорил о свободе. Лягушонок не видел того, что видел Гракх. Он говорил о справедливости, о том, что освободит дочку.\nГракх сжал копьё. Сердце билось ровно. \nОн не знал, что это за женщина, но он знал - она главная. Гракх прислушался к серьге как она реагирует на эту женщину. Она не похожа на ту, кто будет драться. Она похожа на ту, кто будет говорить. И договариваться с ней на языке силы, как с гоблинами, не получится.\nГракх перевёл взгляд на К'варсио. Может, лягушонок прав. Может, с ней можно поговорить. Может, она не враг.\nГракх остался в тени. Наблюдал. Ждал. Смотрел, как она подносит увеличительное стекло к камням, как читает надписи, как гоблины слушаются её без страха - только с усталостью.\n\n/ Остаюсь в скрытности. Наблюдаю за девушкой и гоблинами, запоминаю её манеру поведения, речь, движения. Ищу, где она хранит якорь. Пока не вмешиваюсь. Если она уйдёт в палатку - попытаюсь подобраться ближе. Если нет - жду, пока К'варсио подойдёт и начнёт разговор. Готов действовать в зависимости от того, как она ответит.",114768,null],[175564,"2026-08-27T20:47:42",5,"— Тогда, я заставлю ква-госпожу отпустить вас. Где она?",175536,null],[175569,"2026-08-27T20:49:26",41,"Якоря при девушке нет и вы не знаете, как он выглядит",114768,null],[175570,"2026-08-27T20:49:41",41,"Харбит \n\n— Я покажу… а этот злой монстр с тобой ведь?",175564,null],[175578,"2026-08-27T20:50:58",5,"Лягушонок смотрит в сторону, где в последний раз видел Гракха.\n\n— Да... Он пришёл за квакой-то Дженни. И он правда злой.",175570,null],[175581,"2026-08-27T20:51:48",52,"/поправил",175569,null],[175585,"2026-08-27T20:53:10",41,"— Дженни, у нас есть такая… нам пришлось запереть её в повозке и тщательно следить… но мы ею пользуемся, так как воинов почти всех убили …(",175578,null],[175597,"2026-08-27T20:55:48",5,"— Заперли и пользуетесь? Зачем? Где?",175585,null],[175600,"2026-08-27T20:57:44",52,"Гракх услышал слова лягушонка. \"И он правда злой\". Он не обиделся. Не расстроился. Просто отметил для себя — лягушонок так думает. И это не имело значения.\nА потом он услышал другое. Имя. Дженни. Заперта. В повозке.\nГракх замер. Пальцы сжали копьё сильнее.\nГоблин сказал, что они пользуются ею. Что воинов почти всех убили. Значит, она жива. Значит, она здесь. И они её держат.\nГракх перевёл взгляд на палатку, на девушку, которая вышла оттуда, на гоблинов, которые копошились в камнях. Мысли бешено проносились в голове, но лицо оставалось спокойным. Он знал одно: если они увидят его сейчас - всё будет сложнее.\nОн отступил на шаг в тень, скользнул за статую и замер. Ждал. Слушал. Нужно было понять: где повозка? Где её держат? И как к ней подобраться, не поднимая шума.\nГракх перевёл взгляд на палатку. Главная - там. Если он хочет понять, что здесь происходит, где якорь, где Дженни - ответы внутри.\nОн двинулся. Бесшумно, как тень. От статуи к камню, от камня к пологу палатки. Пальцы коснулись ткани — грубая, плотная, скрывает свет. Он замер у входа, прислушиваясь.\nТишина. Ни голосов, ни шагов.\n\n/ Пытаюсь проникнуть в палатку скрытно. Ищу любое упоминание якоря, сердца леса, Дженни.",114768,null],[175609,"2026-08-27T21:00:47",52,"/не идет рол))",114768,null],[175628,"2026-08-27T21:06:05",41,"( ой ща будет",114768,null],[175721,"2026-08-27T21:31:09",41,"Ты без труда пробираешься по теням, статуям, бликам ручья, солнечным лучам. Достаточно эффективно чтоб оказаться в палатке быстро. Слишком быстро. \n\nВ поисках сердца ты раскрываешь ящики, мешки, дневники. Ничего нет… и тут у твоей шеи оказывается лезвие\n\nСначала проявилась оно, затем рука, и лицо в маске. Девушка , что раньше успешно сливалась с белым камнем смогла подойти к тебе в невидимости. \n\nТихий смешок.\n\n— Якоря здесь нет.",114768,null],[175777,"2026-08-27T21:57:30",41,"@Farkanis .",114768,null],[175812,"2026-08-27T22:14:43",41,"На шум в палатке пришла посмотреть лично Фуюми и её рабы. \n\n#Фуюми \n\n— Что за бесовщина?! Каламити, Как давно он здесь?! \n\n#Каламити\n\nКуноити не снимая маску ответила. \n\n— С тех пор как вы отсюда вышли... Он прошел и надеялся остаться незамеченым. Якорь я перепрятала. \n\nЧетко и холодно прозвучали слова девушки, будто ты не первый нападающий на них",114768,null],[175815,"2026-08-27T22:15:45",41,"В это время Харбит подвел грунга к тому месту, Откуда раньше следил Гракх. Теперь Они видели толпу гоблинов и Фуюми у палатки",114768,null],[175816,"2026-08-27T22:15:55",41,"@elsio28  .",114768,null],[175852,"2026-08-27T22:22:47",5,"— Харбит! Что там происходит? Кто эта девушка? (?)",175815,null],[175855,"2026-08-27T22:23:33",41,"— это наша Госпожа...Фуюми. А вообще я не знаю. Куда пропал твой страшный друг?",114768,null],[175858,"2026-08-27T22:25:26",5,"— Должно быть, он услышал о Дженни и побежал сам искать. Никвакой выдержки! А теперь попался... А я должен заставить ква-госпожу отпустить вас",114768,null],[175859,"2026-08-27T22:26:21",41,"— и его, должно быть...а то есть там одна особа,,, крайне страшная... Её зовут \n\nКаламити",114768,null],[175861,"2026-08-27T22:26:47",5,"— Страшная? Что она может?",175859,null],[175869,"2026-08-27T22:30:00",41,"— она словно тень и слышит Все, что говорят другие рабы. Она одета в белое, но мы никогда не не видим(",114768,null],[175872,"2026-08-27T22:31:00",5,"— Она охраняет ква-госпожу? Только она? А что делает Дженни?",175869,null],[176038,"2026-08-27T23:35:55",41,"— На счет первого ты прав, Кхм. А Джени нас сюда провела из деревни",175872,null],[176099,"2026-08-28T00:24:39",52,"Гракх не шелохнулся, когда лезвие коснулось его шеи. Он стоял, глядя на маску Каламити через плечо, и в его голове уже сложилась картина: ящики пусты, дневники без ответа, а якорь - перепрятан. Она ждала его. Знала, что он придёт.\nГолос Фуюми раздался снаружи, и Гракх услышал, как она вошла в палатку.\n\n— Что за бесовщина?! Каламити, как давно он здесь?!\n— С тех пор как вы отсюда вышли... Он прошёл и надеялся остаться незамеченным. Якорь я перепрятала, — ответила куноити холодно и ровно.\n\nГракх медленно перевёл взгляд на вошедшую Фуюми, но не повернул головы - только глазами. Потом снова посмотрел на маску Каламити и сказал тихо, чтобы слышали обе:\n- Я пришёл за Дженни и за якорем. У меня договор с Наму - я возвращаю сердце леса, она даёт мне силу.\n\nОн выдержал паузу.\n\n- Если Дженни жива и якорь вернётся на место - я уйду. И вы продолжите свои раскопки и сможете покинуть это место. Но если она мертва или ранена, или если якорь пострадал - ни одна из вас не выйдет отсюда живой.\n\nГракх сказал это без угрозы в голосе. Просто констатировал факт.\n\nОн стоял и ждал. Лезвие у шеи, голоса вокруг, тени на стенах палатки. И внутри - только две мысли: Дженни здесь. Якорь должен быть возвращён.\n\n/ Стою неподвижно. Говорю ровно, без угрозы, но твёрдо. Жду реакции Каламити и Фуюми. Если уберут лезвие - готов к диалогу. Если нет - оцениваю возможность перехватить инициативу. Серьга в фокусе внимания. Если начнёт реагировать - заготавливаю наложение тьмы на всю палатку.\n\n@sweetkittywitch @elsio28",114768,null],[176101,"2026-08-28T00:26:19",41,"( тебе требуются компоненты для этого заклинания?",114768,null],[176102,"2026-08-28T00:26:30",52,"/ нет",114768,null],[176103,"2026-08-28T00:27:27",41,"( бросай инициативу сразу. Дам шанс",114768,null],[176104,"2026-08-28T00:27:51",41,"( или... Ща",114768,null],[176105,"2026-08-28T00:28:40",41,"/r d20+6 атака по шее кинжалом",114768,null],[176107,"2026-08-28T00:28:50",41,"( ебаш тьму и ини",114768,null],[176109,"2026-08-28T00:29:42",52,"/roll +d20+3",114768,null],[176111,"2026-08-28T00:30:01",41,"/r d20+3 ини Каламити",114768,null],[176113,"2026-08-28T00:30:18",41,"/r d20+2 ини Фуюми",114768,null],[176115,"2026-08-28T00:30:32",41,"/r d20+1 ини гоблинов",114768,null],[176118,"2026-08-28T00:32:09",52,"/метогеймовый вопрос я видел факел/источник огня в палатке?",114768,null],[176120,"2026-08-28T00:32:35",41,"( Они не горят, светло",114768,null],[176121,"2026-08-28T00:32:50",52,"/это не важно, они там есть?",114768,null],[176122,"2026-08-28T00:33:10",41,"Да",114768,null],[176123,"2026-08-28T00:33:21",41,"У выхода и светильник на столе",114768,null],[176128,"2026-08-28T00:46:06",52,"Гракх резко ушёл вниз, уходя из-под клинка. Лезвие скользнуло по коже, оставляя тонкий порез, но не глубокий. В то же мгновение он выбросил руку вперёд, выпуская из пальцев сгусток чистой тьмы. Она вырвалась из его ладони, разрастаясь в центре палатки, и через секунду помещение заполнила непроглядная чернота — густая, липкая, непроницаемая даже для тёмного зрения.\n\n@sweetkittywitch",114768,null],[176129,"2026-08-28T00:47:19",41,"( а какой огонь ?",114768,null],[176130,"2026-08-28T00:47:54",52,"/вот этот, я опракинул масленую лампу спецално на свитки на столе",176123,null],[176131,"2026-08-28T00:48:33",41,"( я не хочу душить, прокинь мне акробатику",114768,null],[176132,"2026-08-28T00:49:09",52,"/roll 1d20+6",114768,null],[176134,"2026-08-28T00:49:19",41,"Ок, поджог будет",114768,null],[176135,"2026-08-28T00:50:13",41,"( а хотя че я такая добрая",114768,null],[176136,"2026-08-28T00:50:22",41,"( заявка была на тьму",114768,null],[176137,"2026-08-28T00:50:28",41,"( а не на целый пост",114768,null],[176138,"2026-08-28T00:51:02",41,"( не парься, чат гпт напишет новый с учетом заготовленного действия",114768,null],[176139,"2026-08-28T00:52:06",41,"Ты наложил тьму, вернемся к этой части. Если перепадет ход, оставим все как есть + действие",114768,null],[176141,"2026-08-28T00:54:07",52,"/обрезал. действуй)",114768,null],[176142,"2026-08-28T00:57:46",41,"Магическая тьма накрыла палатку, послышался лишь крик госпожи Фуюми, которая стояла снаружи. \n\nОна кричала: \n\n— ЧЕРТ ТЕБЯ ПОБЕРИ, КАЛАМИТИ, НЕ ПОРВИ ЗАПИСИ\n\nКаламити была бесшумна. Она не видела Гракха, но и он не видел её. Двое искусных бойцов находились в равных условиях для сражения. \n\nЛязг лезвия, что покинуло ножны и мгновенный удар в живот с ноги. \n\nЗатем тот самый короткий смешок",114768,null],[176143,"2026-08-28T00:58:16",41,"/r d20+6 катана d20+6 нога",114768,null],[176145,"2026-08-28T00:58:47",52,"помеха)",114768,null],[176146,"2026-08-28T00:59:04",41,"( у неё по стат блоку преимущество когда ты её не видишь",114768,null],[176147,"2026-08-28T00:59:43",41,"/r d8+4 катана d4+2 нога",114768,null],[176149,"2026-08-28T00:59:54",41,"( повезло повезло",114768,null],[176150,"2026-08-28T01:00:35",41,"( хотя перед твоим действием пусть К´Варсио кинет ини",114768,null],[176151,"2026-08-28T01:00:45",41,"Ему нужно будет добежать",114768,null],[176152,"2026-08-28T01:02:31",52,"/17 хп осталось",114768,null],[176158,"2026-08-28T08:58:27",5,"/r +2",114768,null],[176160,"2026-08-28T09:00:00",52,"/ну теперь понеслась))) сейчас выдам пост )",114768,null],[176161,"2026-08-28T09:01:56",52,"/сколько футов ширина выхода из шатра? 5 или 10?\n@sweetkittywitch",114768,null],[176178,"2026-08-28T10:52:21",52,"/roll +d20+6",114768,null],[176185,"2026-08-28T10:53:13",52,"/roll 1d8+1d6+3",114768,null],[176188,"2026-08-28T10:54:18",52,"/ 1d6 это расовая способность от внезапной атаки багбира",114768,null],[176191,"2026-08-28T10:56:11",52,"/а блин там 2d6",114768,null],[176192,"2026-08-28T10:56:31",52,"/roll 1d6",114768,null],[176194,"2026-08-28T10:56:46",52,"/ 11 урона в сумме",114768,null],[176206,"2026-08-28T11:07:20",41,"Копье насквозь пронзает Фуюми, заставив безоружную девушку в настоящем шоке упасть на спину, истекая кровью. Она не успевает ничего сказать, слишком быстро теряя сознание от потери крови. \n\nГоблины паникуют. \n\nКаламити — драгоценная рабыня Фуюми оказывается в ловушке",114768,null],[176208,"2026-08-28T11:08:02",41,"( ща распишу пх",114768,null],[176213,"2026-08-28T11:10:50",41,"(ПХ: \n\nКаламити. \nГракх\nК´Варсио\nГоблины\nФуюми",114768,null],[176219,"2026-08-28T11:34:25",52,"/ @elsio28 твой ход",114768,null],[176222,"2026-08-28T12:11:10",52,"Де К´Варсито 😅",114768,null],[176223,"2026-08-28T12:12:59",5,"— Что там происходит?\n\nК'варсио скачет вниз к палатке и испуганно вертит головой. По пути достал один меч.\n\n— Гоблины, успокойтесь, мы вас освобождаем! Скоро вы сможете выйти отсюда! Никто из вас не пострадает!",114768,null],[176224,"2026-08-28T12:13:13",5,"/ ход",114768,null],[176227,"2026-08-28T12:17:24",41,"( убеждение",114768,null],[176228,"2026-08-28T12:17:52",41,"( Как он реагирует на полумертвую Фуюми?",176223,null],[176229,"2026-08-28T12:18:19",5,"/ её видно?",176228,null],[176230,"2026-08-28T12:18:37",5,"/r +2",176227,null],[176232,"2026-08-28T12:18:40",41,"( тебе наверное нет, но она снаружи",176229,null],[176233,"2026-08-28T12:18:50",52,"/ я пытался с ними поговорить) просто из меня такой себе переговорщик)))",114768,null],[176234,"2026-08-28T12:19:48",41,"Харбит оказывает помощь К'варсио\n\n— Послушайте его! Он поможет нам вернуть наших детей!",114768,null],[176235,"2026-08-28T12:20:37",5,"Когда К'варсио добирается до палатки, он обнаруживает лежащую в крови девушку.\n\n— Это ква-госпожа! Я пришёл не убивать, а освобождать!\n\nГрунг склоняется над ней, оказывая первую помощь.\n\n/ Стабилизация хд",114768,null],[176237,"2026-08-28T12:22:24",41,"У тебя получается! \n\nТы смотришь на её тяжелую рану на животе. Капля твоего яда в малых дозах может стать лекарством и хотя бы замедлить кровотечение. \n\nОна стабилизорована.",114768,null],[176238,"2026-08-28T12:23:21",41,"Гоблины же слишком напуганы горящей палаткой и Гракхом в целом\n\n— П-по моему Мы для вас - враги! \n\nВыкрикнул один гоблин",114768,null],[176240,"2026-08-28T12:24:38",5,"— Нет-нет! Квас никто не тронет, обещаю!",176238,null],[176241,"2026-08-28T12:24:52",52,"/ лягушонок не должен кинуть убеждение с преимуществом ?",176234,null],[176242,"2026-08-28T12:25:14",41,"( да , но не кинул пока",114768,null],[176243,"2026-08-28T12:25:36",5,"/ кидаю",114768,null],[176245,"2026-08-28T12:25:53",52,"👀",114768,null],[176246,"2026-08-28T12:25:55",41,"( не судьба",114768,null],[176247,"2026-08-28T12:26:46",52,"/ очень жаль... этих недоверчивых гоблинцев)",114768,null],[176248,"2026-08-28T12:27:08",41,"Фуюми понемногу приходит в себя. \n\n— Вы … не понимаете … сердце нам дороже… \n\nСмотря на горящую палатку, она спросит \n\n— Моя куноичи там ?",114768,null],[176249,"2026-08-28T12:27:45",52,"/ ей никто не ответит, ибо никто кроме меня не знает)",114768,null],[176250,"2026-08-28T12:28:03",41,"( ну, ответит",114768,null],[176251,"2026-08-28T12:28:15",41,"( Они то не видели как она выбежала",114768,null],[176252,"2026-08-28T12:28:16",5,"Грунг склонился над девушкой.\n\n— Зачем вам сердце? Вы украли его у духов",176248,null],[176253,"2026-08-28T12:28:46",41,"— Оно нужно нам сильнее чем… кх\n\nЕй снова стало плохо",176252,null],[176254,"2026-08-28T12:28:57",41,"( Ход Каламити",114768,null],[176255,"2026-08-28T12:29:15",41,"/r d6 урон огнём",114768,null],[176257,"2026-08-28T12:30:27",41,"Море тлеющих лепестков и куноичи оказывается в десяти футах от выхода, злая и готовая направить свой гнев на лягушонка \n\nПросто атака",114768,null],[176259,"2026-08-28T12:30:54",5,"/ за что лягушонка 😭",114768,null],[176260,"2026-08-28T12:30:59",52,"/ а спас бросок от капкана?",114768,null],[176261,"2026-08-28T12:31:04",41,"/r d8+4",114768,null],[176263,"2026-08-28T12:31:13",41,"( не то",114768,null],[176264,"2026-08-28T12:31:20",41,"( фейский шаг",176260,null],[176265,"2026-08-28T12:31:48",52,"./в прямой видимости, там полог опущен и она ослеплена",114768,null],[176266,"2026-08-28T12:33:03",41,"( можно приподнять, пока не горит",176265,null],[176267,"2026-08-28T12:33:25",52,"/всеровно тьма остается",114768,null],[176268,"2026-08-28T12:33:37",41,"( она имеет границы",176267,null],[176269,"2026-08-28T12:34:03",52,"/да 20 футов это вся палатка и я могу в свой ход ее передвигать",114768,null],[176270,"2026-08-28T12:34:19",41,"( сейчас не твой ход. А выход, уже предел",114768,null],[176271,"2026-08-28T12:34:40",41,"/r -d20+4",114768,null],[176273,"2026-08-28T12:34:43",52,"/капкан внутри тьмы",114768,null],[176274,"2026-08-28T12:34:52",41,"( на тебе твой спас",114768,null],[176275,"2026-08-28T12:35:27",41,"( ты хоть сам этот план придумал? А то меня уже бесит",114768,null],[176276,"2026-08-28T12:35:39",52,"/да)",114768,null],[176277,"2026-08-28T12:35:51",41,"( ну и держи себе легкую победу",114768,null],[176278,"2026-08-28T12:36:23",41,"( пропускает ход",114768,null],[176279,"2026-08-28T12:36:27",41,"( или дальше",114768,null],[176281,"2026-08-28T12:36:41",41,"( иди*",114768,null],[176282,"2026-08-28T12:37:21",41,"( но поверь, мне очень не нравится как ты участвуешь",114768,null],[176283,"2026-08-28T12:37:42",41,"( я буквально не верю, что со мной играешь ты",114768,null],[176284,"2026-08-28T12:38:12",52,"/ 1d4 урона капкана, и следуйшее спас броски уже по силе\n\n Окей могу описывать криво но своими словами",114768,null],[176285,"2026-08-28T12:38:36",41,"( пиши криво , но просто хватит уже",114768,null],[176296,"2026-08-28T12:53:22",52,"Гракх увидел как К´Варсио ворвался в заварушку пытаюсь упокоить гоблинов. Внезапно из палатки раздаля знакомый щелчок метала - это был капкан. Поскольку из-за полога не появилась фигура было понятно что цель попалась в ловушку\nБагбир рванул к палатке держа копье на готове. Пробегая мимо К´Варсио он сказал:\n- Я пытался с ними договорится, как и обещал тебе. Не получилось... \nОн проскользил в сторону шатра и остановился за 10 футов до входа - ровно там, где его удары бы доставали цель, но противник бы не смог до него дотянутся и стал наносить серию ударов\n\n/остановился за 10 футов и наношу урон Каламити копьем и безоружный удар. Чтоб дотянутся до меня ей нужно выбраться из капкана и выйти из шара.",114768,null],[176300,"2026-08-28T12:54:36",52,"/roll +d20+6 (по обездвиженному противнику)",114768,null],[176302,"2026-08-28T12:55:13",52,"/r 1d8+3",114768,null],[176305,"2026-08-28T12:55:47",52,"/r 1d4+3",114768,null],[176308,"2026-08-28T12:56:14",52,"/ 15 урона, я закончил",114768,null],[176311,"2026-08-28T12:57:09",41,"Куноити издает приглушенный за маской крик\n\nПараллельно в новом раунде загорается",114768,null],[176312,"2026-08-28T12:59:23",5,"Грунг взял Фуюми на руки и отошёл от шатра. Параллельно успокаивая гоблинов.\n\n— Мы почти закончили. Вас никто не тронет, не вмешивайтесь. Я верну вас домой",114768,null],[176313,"2026-08-28T12:59:58",41,"( кидай с преимуществом",114768,null],[176314,"2026-08-28T13:00:05",5,"/r +d20+2",114768,null],[176316,"2026-08-28T13:00:13",41,"( работает",114768,null],[176317,"2026-08-28T13:00:21",41,"( первый раунд пройден",114768,null],[176318,"2026-08-28T13:00:26",41,"( хотя",114768,null],[176319,"2026-08-28T13:00:38",41,"( у тебя соревнование с Фуюми",114768,null],[176320,"2026-08-28T13:01:16",41,"— Не слушайте эту жабу! Сердце можно использовать и освободиться! Они лишь мародеры! Пришли забрать сердце себе !",114768,null],[176321,"2026-08-28T13:01:42",41,"/r -d20+2 убеждение Фуюми, помеха из за несостыковки",114768,null],[176323,"2026-08-28T13:01:44",52,"/надо было ее добить)",114768,null],[176324,"2026-08-28T13:02:15",41,"( первый раунд пройден",114768,null],[176325,"2026-08-28T13:02:29",52,"/погладь ее по лицу ядовитой лапкой)",114768,null],[176326,"2026-08-28T13:02:53",41,"Гоблины бездействуют. \n\nФуюми хочет сопротивляться, но не может из за боли",114768,null],[176327,"2026-08-28T13:03:15",5,"— Ква-госпожа, эти гоблины больше не твои рабы. Отныне они свободны!",176320,null],[176328,"2026-08-28T13:03:49",41,"#Фуюми\n\n— Они даже сбежать от меня не смогут, грубиян!",176327,null],[176329,"2026-08-28T13:04:20",5,"*заглянул в глаза*\n\n— Почему не смогут? Как ты их остановишь теперь?",176328,null],[176330,"2026-08-28T13:05:10",41,"#Фуюми\n\n— Я дочь знатного рода с востока, их начнут искать даже здесь за меня!",176329,null],[176331,"2026-08-28T13:05:43",41,"( снова ход Каламити , боевая ситуация действует",114768,null],[176334,"2026-08-28T13:06:13",5,"— Вот квак! Тогда их отпустят в обмен на тебя!",176330,null],[176335,"2026-08-28T13:06:27",5,"// окей, я пропаду на полчаса",114768,null],[176336,"2026-08-28T13:06:45",41,"Она кричит от невыносимых ран и вновь отчаянно пытается выбраться. Печать на её теле активируется от слов лягушонка \n\n— ААААААА",114768,null],[176338,"2026-08-28T13:07:07",41,"/r -d20+5",114768,null],[176340,"2026-08-28T13:07:19",41,"( кажется она берсеркнулась",114768,null],[176341,"2026-08-28T13:07:22",52,"/ о как))",114768,null],[176342,"2026-08-28T13:07:41",52,"/ шанс такого события был крайне мал))",114768,null],[176344,"2026-08-28T13:08:16",41,"/r d20+6 d20+6 атака с ноги и атака мечом по Гракху",114768,null],[176346,"2026-08-28T13:08:28",41,"( 16 попало ?",114768,null],[176347,"2026-08-28T13:08:46",52,"/ кд 16",114768,null],[176349,"2026-08-28T13:09:04",41,"/r d8+4 d4+2",114768,null],[176352,"2026-08-28T13:09:17",41,"( 15 урона по Гракху",114768,null],[176353,"2026-08-28T13:10:16",52,"/ а урон огня по ней ?) в начаое хода)\nу меня 3 хп, и видимо у нее 3 атаки так как она потратила действие на спас бросок )",114768,null],[176354,"2026-08-28T13:10:25",41,"( был",114768,null],[176355,"2026-08-28T13:10:54",52,"/ окей живучая) какое у нее состояние физическое сейчас?",114768,null],[176356,"2026-08-28T13:10:54",41,"( вообще у неё 3",176353,null],[176357,"2026-08-28T13:11:01",41,"( но я вас щажу",114768,null],[176358,"2026-08-28T13:12:31",41,"Катана Каламити заходит глубоко в брюхо Гракха. Затем удар коленом вводит её ещё глубже, заставляя Гракха отойти назад. Она выходит перед ним. Её ноги обгорели и дрожат, волосы тоже подпалились, как и спина. Часть одежды отчаянно придерживается на ней, не давая оголить самые деликатные места на её теле",114768,null],[176359,"2026-08-28T13:12:41",41,"( Твой ход",114768,null],[176360,"2026-08-28T13:13:06",41,"( у тебя преимущество по ней на ход за счет её неустойчивости",114768,null],[176363,"2026-08-28T13:14:29",52,"/ я пассивным восприятием могу оценит выдержит она мою серию атак в этом ходу или нет? В общем могу ее сейчас добить или нет?",114768,null],[176365,"2026-08-28T13:15:06",41,"( Как у тебя самый высокий урон в лучшем случае?",114768,null],[176368,"2026-08-28T13:15:42",52,"/ 1d8+2d4+9",114768,null],[176369,"2026-08-28T13:16:04",41,"( боюсь , тебе придется очень постараться",114768,null],[176373,"2026-08-28T13:20:43",52,"Гракх из последних сил, истекая кровью сжал копье в руках направил древко в голову в врага.",114768,null],[176374,"2026-08-28T13:20:58",52,"/r +d20+6",114768,null],[176376,"2026-08-28T13:21:09",52,"/попал?",114768,null],[176377,"2026-08-28T13:21:41",41,"( да",114768,null],[176378,"2026-08-28T13:22:02",52,"/r 1d8+3",114768,null],[176380,"2026-08-28T13:22:24",41,"( шквал?",114768,null],[176381,"2026-08-28T13:22:54",52,"/ не 3хп куда надо по тапкам давать и пере группироваться)",114768,null],[176382,"2026-08-28T13:23:14",41,"( ок",114768,null],[176383,"2026-08-28T13:23:35",52,"/опиши ранение",114768,null],[176384,"2026-08-28T13:25:04",41,"Ты врезал ей в живот, заставив покоситься, в её глазах отразилась печать и она вновь готова была нанести удар",114768,null],[176389,"2026-08-28T13:32:32",52,"Гракх стоял, истекая кровью. Катана Каламити вошла глубоко в брюхо. Он сжал зубы, прижав руку к ране, и сделал шаг назад. Потом ещё один. Он перевёл взгляд на К'варсио, на Фуюми в его руках, на гоблинов. Если он упадёт сейчас - Дженни не найдёт. А она где-то здесь. Гракх разорвал дистанцию, позволяя ветру подхватить его. Шаг и тени, камни, статуи смешались в одну полосу. Он ушёл за массивную каменную статую, вросшую в землю, скрываясь в полном укрытии. Прижался спиной к холодному камню, зажимая рану. Дышал тяжело, но ровно. Он ждал. Если Каламити выйдет, он увидит её первой.\n\n/ Использую поступь ветра (110 футов), ухожу в полное укрытие за статуей. Если Каламити догонит, заготавливаю удар копьем.",114768,null],[176402,"2026-08-28T13:57:08",41,"Каламити обернется к грунгу\n\n— отдай агаси Фуюми...",114768,null],[176403,"2026-08-28T13:58:11",41,"#Фуюми \n\n— Каламити, как тебя так поймали?! Ты стоила дороже чем оказалась! Работай!",114768,null],[176404,"2026-08-28T14:01:41",52,"/ @elsio28 добей эту *уку Фумию)",114768,null],[176405,"2026-08-28T14:02:44",41,"( у него планы на неё же",114768,null],[176406,"2026-08-28T14:03:17",52,"/ может если он ее убьет то все рабы свободны станут)",114768,null],[176407,"2026-08-28T14:03:55",41,"( тогда бы они уже сами справились",114768,null],[176408,"2026-08-28T14:04:16",52,"/ они из-за печати не могут)",114768,null],[176409,"2026-08-28T14:04:53",41,"( печати дорогие",176408,null],[176420,"2026-08-28T14:28:07",5,"/ извините, буду через полчаса(",114768,null],[176439,"2026-08-28T15:01:52",5,"— Кваламити, значит и ты рабыня?\n\nГрунг стоит, держа в руках Фуюми.\n\n— Мои дикие сородичи подавляют волю существ и делают из них квабов. А ты и без яда не хочешь свободы. Но даже если квак!\n\n— Ты едва стоишь, а на мне ни царапины. Бой уже проигран. Единственное, что ты можешь сделать для своей ква-госпожи — сдаться сейчас и защищать её в будущем.",114768,null],[176447,"2026-08-28T15:17:03",52,"/ если что я дал по тапкам за спину К'варсио. Если она решит догонять меня, может получить провоцированную атаку от лягушонка.",114768,null],[176452,"2026-08-28T15:20:31",41,"( убеждение обеим",176439,null],[176453,"2026-08-28T15:22:02",5,"/r +2",114768,null],[176455,"2026-08-28T15:22:19",5,"/ никто не хочет слушать лягушонка",114768,null],[176456,"2026-08-28T15:22:30",5,"/ что значит обеим?",114768,null],[176457,"2026-08-28T15:23:46",41,"( на то что прикажет Фуюми и что сделает Каламити",114768,null],[176458,"2026-08-28T15:24:12",5,"/r +2 значит второй раз кидаю?",114768,null],[176460,"2026-08-28T15:24:21",5,"/ эх",114768,null],[176461,"2026-08-28T15:24:27",41,"( я хотела дать преимущество",114768,null],[176463,"2026-08-28T15:24:36",41,"Давай дам отдельно",114768,null],[176464,"2026-08-28T15:24:46",41,"Но выбери на кого",114768,null],[176465,"2026-08-28T15:24:53",52,"/дай ему вдохновение)",114768,null],[176466,"2026-08-28T15:25:11",5,"/ на кваламити",114768,null],[176470,"2026-08-28T15:33:26",41,"Вдохновение дам, но за неожиданно интересный выбор",176466,null],[176471,"2026-08-28T15:34:39",5,"/ это для переброса?",176470,null],[176472,"2026-08-28T15:35:05",41,"( да, но Можешь сохранить",176471,null],[176473,"2026-08-28T15:37:32",5,"/ сохраняю пока",114768,null],[176474,"2026-08-28T15:39:02",41,"Где-то между вами шумит ветер, которого до сего не было в этом закрытом куполом месте.\n\nФуюми явно злится, но на смену гневу приходит непонимание. \n\nКаламити складывает меч, показывая что сдается \n\n— Ты с ума сошла?! По договору Ты должна До смерти обеспечивать мою безопасность. Шансы есть, просто действуй! \n\nВетер слегка продувает волосы Каламити. Кажется... Она тоже слышала этот голос \n\nВ это время сам грунг слышит в этом ветре знакомый, звонкий смех \n\n( отыгрыш вдохновения)",114768,null],[176475,"2026-08-28T15:40:41",41,"( боевая ситуация приостановлена",114768,null],[176476,"2026-08-28T15:41:49",5,"К'варсио тянет лапку к её мечу.\n\n— Квасибо! Мне правда не хотелось никого убивать",176474,null],[176477,"2026-08-28T15:44:57",5,"— А ты...\n\nЛягушонок смотрит на Фуюми в руках.\n\n— Скважи им, что все свободны. Что ваш квоговор завершён.\n\nК'варсио громко квакает, привлекая внимание гоблинов вокруг.\n\n— Квоблины! Остановите работы и отдыхайте. Скоро мы вернём вас домой!",176474,null],[176479,"2026-08-28T15:49:44",41,"#Фуюми\n\n— Нет..нет...кх\n\nОна вновь сжимается от боли в ране\n\n— Ты хоть знаешь, что творишь?! ЭТО СЕРДЦЕ СКОРО УМРЕТ",114768,null],[176480,"2026-08-28T15:49:53",52,"Гракх замер, прикрыв глаза на мгновение. Вдохнул. Холодный воздух смешивался с дымом, гарью и сырой землёй. Он отключил боль, отключил шум голосов — и позволил своим чувствам работать. Запах. Сырость, мох, гнилое дерево. И сквозь всё это - тонкий, едва уловимый запах, который он помнил. Кожа, ткань, что-то тёплое и живое. Дженни.\n\n/Двигаюсь к повозке, ориентируясь по запаху. По пути ищу глазами лечебную траву, чтоб хот как-то восстановить хп. Серьга в фокусе внимания если снова почувствую опасность.",114768,null],[176481,"2026-08-28T15:50:26",41,"Каламити хотела помочь госпоже, но ошалоилено остановилась от её слов",176479,null],[176483,"2026-08-28T15:50:45",41,"Опасности Точно Нет",176480,null],[176484,"2026-08-28T15:51:20",52,"/ Я повозку нахожу и чем похилиться?",176483,null],[176485,"2026-08-28T15:51:22",5,"— Умрёт? Сердце мы вернём духам леса, оно не умрёт у своих хозяев",176479,null],[176489,"2026-08-28T15:58:46",41,"#Фуюми \n\n— Нет, оно расходуется как любое другое сердце!... Крх..\n\nЯ...я лишь хотела использовать его по лучшему назначению! \n\nОна перешла на очень злой японский\n\nЗа неё начала обьяснять Каламити \n\n#каламити\n\n— слушай, лягушенок. Она наверное не понятно выразилась. Видишь сады перед собой? Сердце сохранило Их невредимыми. Им десятки веков, никто не мог их найти до нас... \n\nОбведя сад рукой, Она продолжит\n\n— Сердце может найти и сохранить такое. Если госпожа научится Им пользоваться. Мы сможем восстановить самые забытые закоулки нашей истории",176485,null],[176509,"2026-08-28T16:07:55",41,"( далековато",114768,null],[176510,"2026-08-28T16:08:12",41,"( я хотела описать тебе повозку, из неё не слышно их",114768,null],[176512,"2026-08-28T16:09:06",52,"/ убрал пост) пиши про повозку)",114768,null],[176515,"2026-08-28T16:16:06",41,"( Ща чутка закончим чтоб не ломать нарратив",176512,null],[176516,"2026-08-28T16:16:50",5,"— Вы хотите знаний. Но расквачиваются за вас духи леса. Так не пойдёт. Уходите и найдите другой способ восстанавливать историю",176489,null],[176517,"2026-08-28T16:23:00",41,"#Фуюми \n\n— Ты правда выбираешь этих со дня на день умирающих духов вместо годовой работы таких же моих людей?! Ты хоть знаешь, Сколько здесь полегло в поисках этого сердца?!",176516,null],[176518,"2026-08-28T16:26:12",52,"/ эти нытики сами сюда пришли и решили украсть то что им не принадлежит. 😐 а теперь жалуются на то что они тут померли...\n\nвсе ровно что попытаться ограбить на улице боксера и получить по башне а потом жаловаться...",114768,null],[176519,"2026-08-28T16:26:38",5,"— Значит, ты безжалостно тратила жизни бедных рабов для своих целей. При этом убивая духов. Нет, Фуюми. Твои раскопки окончены. Ква!",176517,null],[176520,"2026-08-28T16:27:21",41,"( туда",114768,null],[176521,"2026-08-28T16:28:23",41,"( а че ты хотел от этой интелегенции?",176518,null],[176522,"2026-08-28T16:29:16",52,"/ у этих эльфов нет чести! нет пива! ))",176521,null],[176523,"2026-08-28T16:29:57",41,"( пов: Эльф один",176522,null],[176524,"2026-08-28T16:30:19",52,"/ это мем) просто сейчас найду)",114768,null],[176525,"2026-08-28T16:30:44",41,"( я знаю",176524,null],[176526,"2026-08-28T16:31:23",52,"/ Не чести! Нет Пива!!(Квест Равандила)",114768,null],[176527,"2026-08-28T16:31:36",41,"( знаю знаю",114768,null],[176667,"2026-08-28T18:54:04",52,"/ @sweetkittywitch что мы ждем ?",114768,null],[176672,"2026-08-28T18:55:21",41,"( я ужинаю",114768,null],[176673,"2026-08-28T18:55:36",41,"( скоро",114768,null],[176676,"2026-08-28T18:59:17",52,"/приятного )",114768,null],[176824,"2026-08-28T21:09:27",41,"В повозке было темно, но Гракх смог увидеть два горчщих, красноватых глаза.\n\n\n— Ррр гаф! \n\nВдруг выпалила Джени\n\n— Видал как меня повязали? \n\nТеперь он видел. Веревки, кандалы и даже намордник сковывали его соседку.\n\nДолжно быть Эта деревенская девушка доставила не мало хлопот, но даже в этой ситуации она не теряла чувство юмора.",114768,null],[176877,"2026-08-28T21:36:11",41,"— Хей, кто тебя так, а? Мне казалось, твоя кожа непробиваемая! \n\nЗа первым замком следовал еще. Дальше веревка и намордник. \n\nОсвободившись Джени потянулась, было хотела дать \"кулачок\" дружбану, но увидела как тот держится за рану.\n\n— Ничего, вернемся в деревню и тебя подлатают! Вы там всех победили? Я уж посмотрела бы на то как у суки Фуюми вытикают последние мозги...",114768,null],[176883,"2026-08-28T21:44:43",41,"— А, его у меня спрятали. Под повозкой, видишь в щели? \n\nОна отступила, позволив увидеть золотое свечение внизу",114768,null],[176885,"2026-08-28T21:46:15",52,"/ вопрос сердце нужно вернуть на какой-то пьедестал или просто наму отдать ?",114768,null],[176896,"2026-08-28T21:49:23",41,"( спроси у Фуюми",114768,null],[176902,"2026-08-28T22:10:17",52,"/ @sweetkittywitch",114768,null],[176917,"2026-08-28T22:33:22",41,"Кристалл сердцевины вошел глубоко в рану, кровь начала стекать в символы вырезанные на нем, но боли больше не было...\n\nПеред глазами Гхара вспыхнул белый свет, за ним слышались взволнованные крики Джени, все еще с надеждой дойти до деревни. \n\nНо воин знал — даже хранитебьница дорог Наму не уведет его от смерти. Пока свет переливался, у Гракха было время решить...",114768,null],[176920,"2026-08-28T22:40:32",41,"«Не пытайся победить духа. Это бесполезно.\nЗаставь его поверить, что ты — та самая точка, вокруг которой ему следует существовать».\n\nПеред Гракхом появляется бесформеный силуэт, который нельзя определить.\n.\n.\n.\n🪢 Мини-игра «Якорь»\nПеред тобой находится древний артефакт — Якорь, связанный с духами леса.\nТвоя задача — попытаться установить связь с духом и заставить его признать тебя.\nУ тебя будет 5 раундов.\nВ каждом раунде ты выбираешь, как именно пытаешься воздействовать на духа, после чего делаешь соответствующую проверку.\nВозможные подходы\nТы можешь использовать:\n🗣️ Харизму — убедить, запугать, приказать или договориться.\n🧠 Интеллект — понять природу духа, его поведение или слабость.\n👁️ Мудрость — почувствовать его намерения и предугадать действия.\n⚔️ Силу — попытаться подавить его физически.\n✨ Магию — использовать знания или способности своего персонажа для установления связи.\nМожно предложить свой вариант действия, если он логично подходит ситуации.\nОграничение\nНельзя два раза подряд использовать один и тот же подход.\nДух будет реагировать на каждую твою попытку.\n\n🎲 Что происходит после броска?\nРезультат каждой проверки влияет на твоё состояние.\nУспешные действия приближают тебя к установлению связи.\nНеудачные могут повлиять на тебя и на поведение духа.\nТочный эффект результата заранее неизвестен.\nНекоторые последствия могут проявиться не сразу.\n\n⚠️ Важное правило\nТы можешь остановиться до окончания пяти раундов.\nНо чем дальше продолжается контакт с Якорем, тем сильнее становится связь между тобой и духом.\nПоэтому у тебя есть выбор:\nрискнуть и продолжить — или прекратить эксперимент.\n\nЦель\nПостарайся добиться того, чтобы дух признал тебя.\nНо помни:\nЯкорь связывает не только духа с человеком.\nЧто именно это означает — тебе предстоит выяснить самому.",114768,null],[176963,"2026-08-28T23:40:30",41,"( кидай",114768,null],[176964,"2026-08-28T23:41:14",52,"/спас бросок по мудрости или проницательность ?",114768,null],[176965,"2026-08-28T23:41:45",41,"( просто прямой бросок",114768,null],[176966,"2026-08-28T23:42:00",41,"( хотя не",114768,null],[176967,"2026-08-28T23:42:06",41,"( проницательность",114768,null],[176968,"2026-08-28T23:42:11",41,"( на силу атака",114768,null],[176969,"2026-08-28T23:43:33",52,"/roll 1d20+5",114768,null],[176971,"2026-08-28T23:47:37",41,"Первый провал.\n\nКонтакт с Якорем оставляет на тебе первый след.\n\nТы чувствуешь, как что-то чужое на мгновение проходит через тело — будто дух пытается понять, кто из вас ты, а кто есть он.\n\nНикакого явного изменения пока не видно, но появляется неприятное ощущение чужого присутствия.\n\nТы понимаешь одно: продолжение контакта может повлиять уже не только на духа, но и на тебя.\n\nТвой следующий ход.",114768,null],[176973,"2026-08-28T23:49:30",41,"Тем временем, в \"реальном\" мире:\n\nПо висящим садам прошла трещина, озареная золотым светом. \n\nФуюми спряталась позади Каламити, отсерегаясь последствий. \n\nДжени не отходит от тела Гракха и пытается безуспешно его разбудить",114768,null],[176974,"2026-08-28T23:49:47",41,"( наверное тут стоп. Ждем Эла",114768,null],[176979,"2026-08-28T23:56:15",52,"/r 1d20+6",114768,null],[176981,"2026-08-28T23:56:35",52,"/ок",176974,null],[176982,"2026-08-29T00:00:23",41,"Второй раз \n\nЯкорь отталкивает тебя.\n\n\nНа этот раз ощущение чужого присутствия становится гораздо сильнее. \n\nНа мгновение тело перестаёт слушаться — пальцы сами дёргаются, дыхание сбивается, а движение получается неестественным, будто уже не ты хозяин своих рук.\n\nНа коже на секунду появляется странный след красноватого цвета, связанный с природой духа, но почти сразу исчезает.\n\nТы понимаешь: Якорь уже начал оставлять на тебе свой след.\n\nИ, кажется, следующий контакт будет опаснее предыдущего.",114768,null],[176983,"2026-08-29T00:00:49",41,"( теперь ждём завтра",114768,null],[176984,"2026-08-29T00:00:58",52,"/кто-то проклял кубы ) 4 из 5 бросков последних ниже 10 )",114768,null],[176985,"2026-08-29T00:02:56",52,"/либо жёсткий рак кубов или следующие 2 броска точно должны быть больше 10)",114768,null],[176992,"2026-08-29T00:47:48",52,"/roll 1d20+5",114768,null],[176994,"2026-08-29T00:48:04",41,"( это прошел",114768,null],[176995,"2026-08-29T00:48:12",41,"( но всё",114768,null],[176996,"2026-08-29T00:48:16",41,"Жди",114768,null],[176997,"2026-08-29T00:48:34",52,"/жду) я спать пошел )",114768,null],[176998,"2026-08-29T00:54:23",41,"Спок",176997,null],[177016,"2026-08-29T06:26:02",41,"@elsio28 если что, жду реакцию",114768,null],[177017,"2026-08-29T06:28:14",5,"/ да, сейчас думаю",114768,null],[177018,"2026-08-29T07:17:44",5,"Грунг испуганно смотрит наверх, на трещину.\n\n— Что происходит? Место рушится?\n\nК'варсио поскакал к телу багбира и осматривает его.\n\n— Почему Гракх без сознания? Дженни, это ведь ты? Что с ним?",176973,null],[177031,"2026-08-29T09:51:56",41,"#Дженни \n\nДевушка, что безуспешно пыталась разбудить друга замечает грунга и слегка пугается, но не от вида, а от неожиданности. \n\n— ты ведь не взбунтовавшийся эксперимент тех ученых?...\n\nОна не долго думала\n\n— Даже если так, Дженни, уже знаешь. \n\nПротянет тебе руку для рукапожатия, которую ты впрочем мог и не развязывать \n\n— Гракху откровенно хуево. Он боялся откинулся и закрыл рану этим ебучем сердцем.. Теперь...\n\nОна немного отойдет в сторону и ты увидишь, как тело багбира медленно обростает золотым криствллом. \n\nВ этот момент \n\nНа небе появится вторая трещина",114768,null],[177032,"2026-08-29T09:52:21",41,"@elsio28  .",114768,null],[177033,"2026-08-29T09:52:31",41,"@Farkanis  .",114768,null],[177035,"2026-08-29T10:07:40",5,"К'варсио быстро пожал руку.\n\n— Он вставил сердце духов в себя? Вот дурак! Надо квытащить его, пока не поздно!\n\nЛягушонок хватается обеими лапками за кристалл и тянет наружу",114768,null],[177036,"2026-08-29T10:08:38",41,"Кристалл тянуть опасно, Он закрывает смертельную рану и буквально врос в багбира",114768,null],[177037,"2026-08-29T10:10:22",5,"— Нет, кристалл уже часть корабля Гракха. Что же делать!?",177036,null],[177038,"2026-08-29T10:15:12",5,"/ можно попытаться понять почему кристалл растет в теле? Магией?",114768,null],[177039,"2026-08-29T10:20:24",41,"( да",114768,null],[177040,"2026-08-29T10:22:39",5,"/r +1",114768,null],[177042,"2026-08-29T10:23:56",52,"/Но это должен быть был мой рол на спасение )\nМожно я потом перед броском сначала рак кубов сниму ?)",114768,null],[177043,"2026-08-29T10:23:56",41,"С духами шутки не шутят. Он определенно бросил вызов одному из них на что-то вроде «подчинения» или вернее сказать пакта. Кто в пакте будет хозяином — решит их внутренняя борьба",114768,null],[177044,"2026-08-29T10:24:19",41,"( мы так не играем , все рандомно",177042,null],[177045,"2026-08-29T10:24:38",52,"/ окей)",114768,null],[177046,"2026-08-29T10:25:45",41,"Взамен Гракх впервые чувствует небольшое облегчение и тепло. Дух услышал его и позволил услышать настоящего себя. Лето, жизнь, теплое солнце, журчание ручья, шелест травы. \n\nВсё это - он. \n\nТвой ход",114768,null],[177047,"2026-08-29T10:27:48",5,"— Гракх, отпусти духа! Не пытайся подчинить его!\n\nЛягушонок кричит багбиру.",114768,null],[177048,"2026-08-29T10:30:02",41,"А захочет ли дух отпустить его? \n\nГрунга Гракх не слышит",114768,null],[177052,"2026-08-29T11:01:49",52,"/roll 1d20+6",114768,null],[177054,"2026-08-29T11:02:16",52,"/Ееееее 🥳",114768,null],[177055,"2026-08-29T11:12:52",41,"Ты будто почувствовал улыбку этого духа в ответ. \n\nУ него не было четкого силуэта, Но ты смог разглядеть его огненные, величественные крылья. Это видение, которое он тебе дает.",114768,null],[177056,"2026-08-29T11:13:03",41,"( твой решающий бросок",114768,null],[177057,"2026-08-29T11:14:09",52,"/ можно прокинуть через инициативу ?) Это мой максимальный бросок +d20+6 ?",114768,null],[177058,"2026-08-29T11:15:03",41,"( хорошо",114768,null],[177059,"2026-08-29T11:15:11",41,"( Но",114768,null],[177060,"2026-08-29T11:15:16",41,"( не преимущество",114768,null],[177061,"2026-08-29T11:15:41",52,"/окей",114768,null],[177062,"2026-08-29T11:18:21",52,"/ там ляшушенок ничего не хочет прокинуть ?) Просто страшновато 4 раза выкинуть больше 10 мало вероятно )",114768,null],[177063,"2026-08-29T11:19:06",41,"( ну Сеня",114768,null],[177064,"2026-08-29T11:19:06",41,"( давай",114768,null],[177065,"2026-08-29T11:20:00",52,"/пошел писать пост ) возможно последний за этого перса )",114768,null],[177066,"2026-08-29T11:22:49",5,"/ лягушонок может только эвакуацию организовать",177062,null],[177080,"2026-08-29T11:50:42",52,"Гракх смотрел на огненные крылья. Они не жгли, а грели. Как то самое лето, которое он никогда не знал, но которое дух показал ему. Тепло разливалось по груди, по рукам, по той самой ране, где теперь пульсировал кристалл. Дух не нападал. Он ждал. Наблюдал. Оценивал. Гракх шагнул ближе. Не с вызовом, а с пониманием. Он чувствовал, как их воли соприкасаются, как две реки текут рядом, готовые либо слиться, либо разойтись навсегда.\nВнутри него поднималась тяжесть. Тени вокруг сгущались, но он не давал им разрастись. Он выдохнул медленно, глубоко, и позволил себе просто быть. Быть здесь. С этим существом. С этой силой, которая теперь пульсировала в его крови.\n\n- Я не враг тебе, - сказал он тихо. - И не хозяин. Я тот, кто идёт своим путём. Если ты хочешь идти со мной то иди. Если нет... я приму твой выбор.\nОн сделал ещё один шаг вперёд и положил руку на то место, где дух проявлял себя ярче всего.\n\n- Но я не отступлю. Я не просил тебя спасать мне жизнь. Но раз уж ты здесь то давай решим это по нашему. Как два воина. Без лжи. Без игр.\nГракх замолчал. Он ждал ответа. Не знал, каким он будет. Но знал... он готов принять любой исход.\n\n/ Внутри белой пустоты. Стою перед духом. Готов к финальному контакту.",114768,null],[177081,"2026-08-29T11:51:04",52,"/roll 1d20+6",114768,null],[177084,"2026-08-29T11:51:35",52,"/ожидаемо... достаточно 14?",114768,null],[177087,"2026-08-29T11:51:52",41,"( ровно",114768,null],[177096,"2026-08-29T11:57:11",41,"Дух ответил своей песней, отвающей на все вопросы в душе. \n\nЧто такое лето? \n\nКак стать сильнее? \n\nЧто делает тебя настоящим?\n\nПеснь звучала искренне и торжественно.\n\nТеперь он видел, что за дух стоял перед ним. Птичье тело и голова прекрасного человека. За его зранью было понятие, мужчина это или женщина — это...",177080,null],[177102,"2026-08-29T12:01:43",41,"... Сирин пойдет с тобой.",114768,null],[177105,"2026-08-29T12:02:34",52,"/ чуть позже отпишу)",114768,null],[177107,"2026-08-29T12:08:19",41,"( я пока дополню",114768,null],[177112,"2026-08-29T12:14:23",41,"Вы видели как трещины расползаются, мозайка рушится, дома сыпятся в пыль. \n\nСердца больше нет \n\nГракх обнаруживает на месте кристалла шрам, но не самое сердце\n\nСирин село неподалеку от вас на ветку дерева. \n\nТеперь вы были в лесу, откуда вас проважала Наму. Здесь же были гоблины и Фуюми",114768,null],[177134,"2026-08-29T13:10:54",52,"Гракх открыл глаза. Он лежал на сырой земле, сжимая рукой живот. Там, где раньше зияла глубокая рана, теперь был шрам - грубый, багровый, похожий на корни старого дерева. Но не было боли. Только тепло, которое разливалось по груди. Он поднял голову.\nВокруг был лес. Тот самый лес, откуда они пришли. Мозайка рушилась в пыль, и каждая трещина в воздухе гасила последние остатки волшебства. На ветке неподалёку сидел Сирин. Смотрел на него спокойно, без слов.\nГде-то рядом копошились гоблины, сбившись в кучу. Фуюми лежала на земле, прижатая чьей-то рукой. Каламити стояла, сложив меч, и молчала. Всё было кончено.\nГракх медленно поднялся. Шагнул к Сирину, остановился и посмотрел в его глаза.\n\n- Ты останешься со мной? - спросил он тихо своим грубоватым голосом.\n\nОн ждал ответа, чувствуя, как внутри него разливается что-то новое. Тёплое. Живое. Как будто он держал в груди маленькое солнце. Он был готов идти дальше и знал, что теперь он не один.",114768,null],[177135,"2026-08-29T13:11:29",41,"( вы уже там",114768,null],[177138,"2026-08-29T13:19:39",52,"/ поправил",114768,null],[177140,"2026-08-29T13:29:54",41,"Сирин тихо посмеялся, его голос был очень средним и андрогинным, но так же очень живым и теплым. \n\n— Меня зовут Лето, я буду с тобой столько, сколько захочу, воитель) \n\nПо всему лесу были разбросаны небольшие безделушки, что когда-то были духами. Окрашенные шишки, маленькое ожерелье, маска духа Наму. \n\nОглянувшись на неё, сирин сказал. \n\n— Матушка мертва, но … благодаря вам я выжил, спасибо вам, герои)",114768,null],[177141,"2026-08-29T13:29:55",5,"— Что это за птица? Что стало с сердцем!?",177112,null],[177142,"2026-08-29T13:30:31",41,"Вы поняли это все как один.",114768,null],[177143,"2026-08-29T13:30:38",41,"Сердце мертво",114768,null],[177149,"2026-08-29T13:36:57",5,"— Наму, это ты?",177140,null],[177152,"2026-08-29T13:39:16",41,"#Лето\n\n— нет, глупыш. Я её лучшее создание, дух сердца леса)) моя сила давно не такая как раньше , но я готов помочь тому, кто показал мне свою силу) А Наму… Как и все духи, уже мертва",177149,null],[177173,"2026-08-29T14:00:45",5,"— Что? Квак же так! Я хотел спасти их!",177152,null],[177174,"2026-08-29T14:08:55",41,"Сирин пархнул ближе к К´Варсио, утирая ядовитые слезы крылом \n\n— Ты и твой друг спасли меня. Это не сможет тебя утешить, духам оставалось недолго. Но… я останусь и буду оплакивать этот лес до конца своих времен)",177173,null],[177175,"2026-08-29T14:10:06",5,"— А ты... добрая? Будешь помогать деревне?",114768,null],[177176,"2026-08-29T14:11:35",41,"— Я само решаю, когда и к кому мне быть добрым) Но, если мы ещё остановимся здесь. Я обязательно помогу и деревне, и несчастным рабам вновь ощутить счастливое лето)",114768,null],[177177,"2026-08-29T14:12:19",5,"— Ты знаешь что-то о рабах? Я собираюсь отпустить всех квоблинов!",114768,null],[177178,"2026-08-29T14:13:28",41,"— Меня впечатлил твой друг … в большей степени. Если он пойдет за ними, пойду и я )",114768,null],[177179,"2026-08-29T14:18:04",52,"Гракх стоял неподвижно, глядя на Сирина. Лето. Дух, который теперь сидел на ветке и смотрел на него живыми, тёплыми глазами. Внутри всё ещё пульсировало то тепло, которое он принял в белой пустоте, и теперь оно было частью его.\nОн перевёл взгляд на землю. Вокруг, среди мха и корней, валялись маленькие вещи: окрашенные шишки, ожерелье, обломки того, что когда-то было духами. И среди этого маска. Та самая маска, которую носила Наму. Она лежала на земле, чуть присыпанная листьями.\nГракх не стал спрашивать разрешения. Просто подошёл, присел на корточки и поднял её. Повернул в руках и положил за пояс. Не как трофей. Как память.\nОн поднялся и перевёл взгляд на Каламити и Фуюми. Они были здесь. Рядом. Куноити всё ещё стояла с мечом, Фуюми лежала на земле. Они привели его сюда. Они держали Джени. Они враги.\nГракх не сделал шага в их сторону. Не обнажил оружие. Просто стоял и смотрел, позволяя им видеть, что он знает, кто они. И что он не забыл.\n\n- Я пришёл за Джени, - сказал он ровно, глядя на Фуюми. - И я её забрал. Всё остальное - ваши проблемы.\n\nОн перевёл взгляд на Каламити, задержался на мгновение и отвернулся. Подошёл к Джени и произнёс своим грубоватым голосом:\n- Нам пора уходить.\n\nНапоследок он бросил взгляд на Лето.\n- Спасибо тебе.\nОн не стал звать духа. Не стал требовать. Просто встретился с ним взглядом, приглашая последовать за ним, оставляя выбор за ним самим. И сделал первые шаги в сторону деревни. \n\nПроходя мимо К'варсио, сказал ровно:\n- Справедливости не будет. Но мы вернули то, что смогли. Теперь нужно идти дальше.\n\n/ Поднимаю маску Наму, кладу за пояс. Встаю. Не нападаю, но даю понять, что я их не забыл и не простил. Готов уходить с Джени.",114768,null],[177180,"2026-08-29T14:20:03",41,"#Джени\n\n— Каков пиздец… духи все это время умирали. И у нас остался один этот петух!? \n\nВ ответ на её фразу Лето лишь посмеялось",114768,null],[177181,"2026-08-29T14:20:26",5,"К'варсио разочарованно смотрит на багбира.\n\n— Ну и уходи, бессердечный! Я выведу квоблинов.",114768,null],[177182,"2026-08-29T14:20:48",41,"#Джени \n\n— .. ладно, пофиг. Мы пошли. Удачи тебе, лягушонок",114768,null],[177183,"2026-08-29T14:21:38",41,"Лето взлетел и полетел с ними",114768,null],[177184,"2026-08-29T14:22:25",5,"Грунг сзывает гоблинов к себе.\n\n— Квоблины! Вы теперь свободны! Можете выйти со мной. Много ли у кого остались родственники в заложниках?",114768,null],[177189,"2026-08-29T14:28:22",52,"Гракх уже сделал несколько шагов в сторону деревни, когда услышал голос К'варсио за спиной. Лягушонок собирал гоблинов, говорил о свободе, о родственниках. Гракх остановился. Не обернулся. Просто замер на мгновение.\nОн перевёл взгляд на Лето, который летел рядом с ним. Гракх посмотрел на гоблинов. На их испуганные лица, на то, как они жались друг к другу, не зная, чему верить. Они не были врагами. Они были такими же жертвами, как и он сам. Как Джени.\n\n- Лето, - сказал он негромко, - ты можешь проводить их до границы леса? Чтобы они не заблудились и чтобы с ними ничего не случилось по пути.\nОн выдержал паузу, глядя на духа.\n\n- Они заслуживают шанса начать заново.",114768,null],[177191,"2026-08-29T14:30:00",41,"( погодите немного",114768,null],[177217,"2026-08-29T14:49:23",41,"К тебе подходит Каламити \n\n— подожди, их дети все еще в плену \n\nГоблины смиренно поднимают руки, убирая инструменты\n\n— я знаю как освободить их, но моему договору не понравится, что ты угрожаешь опасностью агаси Фуюми. Мой контракт магический — на мое истинное имя. В его условия можно вписать освобождение гоблинов, но нужно правильно составить эту часть требования",177184,null],[177218,"2026-08-29T14:49:41",41,"Фуюми ревет просто",114768,null],[177220,"2026-08-29T14:51:13",41,"#Лето \n\nСирин посмеялось и легко полетело вокруг багбира и его спутницы. \n\n— Раз ты хорошо попросил об этом, так и быть, проведу по всем заветам моей матушки)",177189,null],[177223,"2026-08-29T15:16:30",5,"— Кваламити, ты поможешь с договором? Я не желаю ничего плохого Фуюми, но рабы должны освободиться! Как писать договор?",177217,null],[177224,"2026-08-29T15:18:46",41,"— я рассуждаю и не смогу ответить на этот вопрос досконально. Ты требуешь того, Что решают высшие сущности. Я сама рабыня и понятия не имею, как освободиться",114768,null],[177225,"2026-08-29T15:19:38",5,"— Ква? А как делать договор?",114768,null],[177226,"2026-08-29T15:21:39",41,"На голову К'варсио садится бабочка, будто заляпаная пятнами краски.\n\n\"Договор обнадеживает, но никогда не значит настоящую свободу. Отпусти гоблинов сейчас и обещаю, Что Мы с тобой спасем их и Каламити в будущем)))\" \n\nГоворил знакомый голос феи",177223,null],[177227,"2026-08-29T15:22:04",41,"\"Помни, творчество ведёт к любви, а любовь к свободе)))\"",114768,null],[177228,"2026-08-29T15:23:02",5,"— Кваспожа? Я отпускаю квоблинов, конечно!",177226,null],[177229,"2026-08-29T15:24:43",41,"\"Ты не сможешь спасти их сейчас без жертв. Но тебе не нужно очернять свое доброе сердце. Доверься мне и отпусти их с Фуюми. Мы вернемся и спасем их вместе, когда ты будешь моим любимым последователем)))\"",177228,null],[177230,"2026-08-29T15:25:30",5,"— Но что мне делать сейчас, кваспожа?",114768,null],[177231,"2026-08-29T15:25:43",41,"#Каламити \n\n— ты говоришь с... Бабочкой?",114768,null],[177232,"2026-08-29T15:26:19",41,"\"стань сильнее, мудрее и обрести друзей. Только с  ними ты сможешь победить)\"",177230,null],[177233,"2026-08-29T15:27:19",5,"/ сек",114768,null],[177234,"2026-08-29T15:28:37",5,"— Это моя кваспожа и покровительница! Она направит меня",177231,null],[177235,"2026-08-29T15:28:53",5,"— Я должен просто уйти? Квак же так?",177232,null],[177236,"2026-08-29T15:30:47",41,"\"Не обещай им, что уйдешь. Обещай, что вернешься вместе с помощью\"",177235,null],[177237,"2026-08-29T15:32:54",5,"К'варсио улыбается бабочке.\n\n— Квоблины, я не могу спасти ваших детей сейчас. Но я обещаю, что вернусь когда найду помощников. Ждите меня и не теряйте надежды!",177236,null],[177238,"2026-08-29T15:35:52",41,"#Харбит\n\n— Спасибо, я верю тебе! Сегодня ты спас нас от жадности госпожи, спасешь и в следующий. Я знаю, ты не подведешь, дружище!... Мою дочку кстати зовут Нона, я очень скучал по ней, поэтому нарисовал втихоря \n\nОн покажет весьма добротный скетч маленькой гоблинши\n\n— Дарю его тебе в награду за спасение, и чтоб ты помнил, ради кого на самом деле борешься, герой!",177237,null],[177241,"2026-08-29T15:38:13",5,"Грунг берет скетч и рассматривает.\n\n— Милая девочка! Спасибо, сохраню картинку как обещание вернуться",177238,null],[177242,"2026-08-29T15:39:20",41,"— будем ждать тебя, К'Варсио! Береги себя \n\nОстальные гоблины уходят вместе с Фуюми и Каламити",114768,null],[177243,"2026-08-29T15:39:45",41,"Скетч на папиросе",114768,null],[177245,"2026-08-29T15:42:20",5,"— Эх, квоблины! Надеюс, я всё сделал по справедливости, моя кваспожа!\n\nК'варсио осматривает узор на бабочке",177242,null],[177248,"2026-08-29T15:44:41",41,"\"Хихихи, удачи, Мой принц)\" \n\nБабочка будто бы поцеловала его и полетела по притихшему лесу, но кажется, где-то на ветру все еще слышны песни — отголоски былых духов",177245,null],[177255,"2026-08-29T15:50:59",5,"— Ква-ква-ква! \n\nК'варсио попрыгал назад к деревне",114768,null],[177261,"2026-08-29T15:56:54",41,"В деревне же Джени рассказала всем, что на самом деле произошло. Её и Фуюми подлечили, а сами ученые попытались по скорее уйти. \n\nПосле долгого приключения, Джени позвала вас на жаркое у себя дома, наверное такого черного жаркого вы не видели никогда своей жизни. Пахнет отвратно, на вкус тоже, но она своей работой была очень довольна. \n\nОдин лишь Лето зерно клевал\n\nМир продолжит идти сам собой, иногда важно не спешить со справедливостью и спасти тех, кого можно спасти с умом. Сегодня вы обошлись с минимальными жертвами и это стоит отметить. Никто не почувствовал боль, духов отпустила паника. Всё закончилось тихо и мирно для них, для деревни, и для вас.",114768,null],[177262,"2026-08-29T15:57:13",41,"( спасибо за игру. Жду рецензию по возможности!",114768,null],[177339,"2026-08-29T16:35:33",5,"/ спасибо за игру",114768,null],[177341,"2026-08-29T16:36:05",52,"/ спасибо за игру всем)",114768,null],[177346,"2026-08-29T16:37:32",41,"( и вам спасибо",114768,null],[177449,"2026-08-29T18:53:14",41,"Запишите 700 опыта себе сразу",114768,null],[177504,"2026-08-29T19:36:25",41,"Закройте тему",114768,null]]);
